function demonLaboUiAssetUrl(path) {
  const cleanPath = String(path || "").trim().replace(/^\/+/, "");
  if (!cleanPath) return "";
  return DEMON_LABO_UI_ASSET_BASE_URL.replace(/\/$/, "") + "/" + cleanPath;
}

