/* =========================
   旧セーブ互換変換
========================= */

function migrateCountMap(value, ids, oldNameToId) {
  const result = Object.fromEntries(ids.map(id => [id, 0]));

  if (!value || typeof value !== "object") {
    return result;
  }

  for (const [key, count] of Object.entries(value)) {
    const id = ids.includes(key) ? key : oldNameToId[key];

    if (id && Number.isFinite(count)) {
      result[id] = count;
    }
  }

  return result;
}

function migrateUnlockedRoutes(value) {
  if (!Array.isArray(value)) return [];

  return [
    ...new Set(
      value
        .map(item => normalizeAdultTypeId(item))
        .filter(Boolean)
    )
  ];
}

function migrateLifeHistory(value) {
  if (!Array.isArray(value)) return [];

  return value.slice(-LIFE_HISTORY_LIMIT).map(item => ({
    ...item,
    teenType: normalizeTeenTypeId(item?.teenType),
    adultType: normalizeAdultTypeId(item?.adultType),
    elderType: normalizeAdultTypeId(item?.elderType),
    finalRoute:
      normalizeAdultTypeId(item?.finalRoute) ||
      normalizeTeenTypeId(item?.finalRoute) ||
      null,
    specialEndingId: endingDefs[item?.specialEndingId]
      ? item.specialEndingId
      : null
  }));
}

