let lastDecay = saved.lastDecay ?? Date.now();
let zeroStartTime = saved.zeroStartTime ?? null;
let careLockUntil = Number.isFinite(saved.careLockUntil) ? saved.careLockUntil : 0;

let sageTimeUntil = Number.isFinite(saved.sageTimeUntil) ? saved.sageTimeUntil : 0;
let redMamushiActive = saved.redMamushiActive === true;
let demonLaboSageRecoveryBlocked = false;
let demonLaboSageTimerEl = null;

function isSageTimeActive(now = Date.now()) {
  return Number.isFinite(sageTimeUntil) && sageTimeUntil > now;
}

function sageTimeRemainingMs(now = Date.now()) {
  return isSageTimeActive(now)
    ? Math.max(0, sageTimeUntil - now)
    : 0;
}

function recoverEnergy(amount) {
  const value = Number(amount) || 0;
  if (value <= 0) return false;

  if (isSageTimeActive()) {
    energy = 0;
    demonLaboSageRecoveryBlocked = true;
    return false;
  }

  energy = clamp(energy + value);
  return true;
}

function syncDemonLaboAdultJokeStates({ announceSageEnd = false } = {}) {
  const now = Date.now();

  if (Number.isFinite(sageTimeUntil) && sageTimeUntil > 0 && sageTimeUntil <= now) {
    sageTimeUntil = 0;
    if (announceSageEnd && !isDead && !zombieState.active) {
      showEventMessage("賢者タイム終了。");
    }
  }

  if (isDead || zombieState.active) {
    sageTimeUntil = 0;
    redMamushiActive = false;
  }

  if (isSageTimeActive(now)) {
    energy = 0;
    redMamushiActive = false;
  }

  if (redMamushiActive && energy < 50) {
    redMamushiActive = false;
  }
}

function createDemonLaboSageTimeTimer() {
  if (demonLaboSageTimerEl && demonLaboSageTimerEl.isConnected) {
    return demonLaboSageTimerEl;
  }

  const host =
    document.getElementById("demonLaboExternalGame") ||
    document.getElementById("demonLaboHeroCard") ||
    document.body;

  if (!host) return null;

  let timer = document.getElementById("demonLaboSageTimeTimer");
  if (!timer) {
    timer = document.createElement("div");
    timer.id = "demonLaboSageTimeTimer";
    timer.setAttribute("aria-live", "polite");
    host.appendChild(timer);
  } else if (timer.parentNode !== host) {
    host.appendChild(timer);
  }

  demonLaboSageTimerEl = timer;
  return timer;
}

function refreshDemonLaboSageTimeTimer() {
  syncDemonLaboAdultJokeStates({ announceSageEnd: true });

  const timer = createDemonLaboSageTimeTimer();
  if (!timer) return;

  if (!isSageTimeActive()) {
    timer.style.display = "none";
    timer.textContent = "";
    return;
  }

  const totalSeconds = Math.max(0, Math.ceil(sageTimeRemainingMs() / 1000));
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;

  timer.textContent =
    "🫥 賢者タイム  " +
    String(minutes).padStart(2, "0") +
    ":" +
    String(seconds).padStart(2, "0");

  timer.style.display = "flex";
}

function syncDemonLaboVitalityDisplay() {
  syncDemonLaboAdultJokeStates();

  const card = document.getElementById("dlParamEnergy");
  if (!card) return;

  const label = card.querySelector(".dl-cute-param-label");

  card.classList.toggle("dl-vitality-mode", redMamushiActive);

  if (label) {
    label.textContent = redMamushiActive ? "精力" : "体力";
  }

  card.setAttribute("aria-label", redMamushiActive ? "精力" : "体力");
}

