function normalizePersonalityBias(value) {
  const result = {
    trouble: 0,
    party: 0,
    honest: 0,
    introvert: 0
  };

  if (!value || typeof value !== "object") {
    return result;
  }

  teenTypeIds.forEach(id => {
    if (Number.isFinite(value[id])) {
      result[id] = Math.max(0, Math.floor(value[id]));
    }
  });

  return result;
}

function normalizeRouteFlags(value) {
  if (!value || typeof value !== "object") {
    return {
      forcedAdultType: null,
      usedSuspiciousDrug: false,
      hiddenGrowthSeed: false,
      hiddenGrowthAwakened: false,
      awakenedRoute: false,
      redemptionCombo: false,
      specialDeathSeed: false,
      zombieReason: null,
      zombieCureBoost: false,
      lifeRewardGranted: false,
      specialEndingRewardGranted: false,
      timeShortcutUsedStages: [],
      personalityBias: normalizePersonalityBias(null)
    };
  }

  return {
    forcedAdultType: normalizeAdultTypeId(value.forcedAdultType),
    usedSuspiciousDrug: value.usedSuspiciousDrug === true,
    hiddenGrowthSeed: value.hiddenGrowthSeed === true,
    hiddenGrowthAwakened: value.hiddenGrowthAwakened === true,
    awakenedRoute: value.awakenedRoute === true,
    redemptionCombo: value.redemptionCombo === true,
    specialDeathSeed: value.specialDeathSeed === true,
    zombieReason:
      typeof value.zombieReason === "string"
        ? value.zombieReason
        : null,
    zombieCureBoost: value.zombieCureBoost === true,
    lifeRewardGranted: value.lifeRewardGranted === true,
    specialEndingRewardGranted: value.specialEndingRewardGranted === true,
    timeShortcutUsedStages: Array.isArray(value.timeShortcutUsedStages)
      ? [...new Set(value.timeShortcutUsedStages.filter(
          key => ["baby", "child", "teen", "adult"].includes(key)
        ))]
      : [],
    personalityBias: normalizePersonalityBias(value.personalityBias)
  };
}

