function createEmptyZombieState() {
  return {
    active: false,
    startedAt: null,
    lastDecay: null,
    originStage: null,
    originRoute: null,
    finalType: null,
    endedAt: null,
    actions: {
      feed: 0,
      roam: 0,
      rest: 0,
      remember: 0
    }
  };
}

function normalizeZombieState(value) {
  const empty = createEmptyZombieState();

  if (!value || typeof value !== "object") {
    return empty;
  }

  const actions = value.actions && typeof value.actions === "object"
    ? value.actions
    : {};

  return {
    active: value.active === true,
    startedAt: Number.isFinite(value.startedAt) ? value.startedAt : null,
    lastDecay: Number.isFinite(value.lastDecay) ? value.lastDecay : null,
    originStage: typeof value.originStage === "string" ? value.originStage : null,
    originRoute:
      normalizeAdultTypeId(value.originRoute) ||
      normalizeTeenTypeId(value.originRoute) ||
      null,
    finalType: zombieTypeDefs[value.finalType] ? value.finalType : null,
    endedAt: Number.isFinite(value.endedAt) ? value.endedAt : null,
    actions: {
      feed: Number.isFinite(actions.feed) ? actions.feed : 0,
      roam: Number.isFinite(actions.roam) ? actions.roam : 0,
      rest: Number.isFinite(actions.rest) ? actions.rest : 0,
      remember: Number.isFinite(actions.remember) ? actions.remember : 0
    }
  };
}

let zombieState = normalizeZombieState(saved.zombieState);

