/* =========================
   イベント状態
========================= */

function createEmptyEventState() {
  return {
    total: 0,
    lastEventId: null,
    history: [],
    nextRandomEventAt: null,
    pendingEventId: null,
    luckBoostCharges: 0,
    chainFlags: {
      labLetterStep: 0,
      zombieMemoryStep: 0
    }
  };
}

function normalizeEventState(value) {
  if (!value || typeof value !== "object") {
    return createEmptyEventState();
  }

  return {
    total: Number.isFinite(value.total) ? value.total : 0,
    lastEventId:
      typeof value.lastEventId === "string"
        ? value.lastEventId
        : null,
    history: Array.isArray(value.history)
      ? value.history.slice(-EVENT_LOG_LIMIT)
      : [],
    nextRandomEventAt: Number.isFinite(value.nextRandomEventAt)
      ? value.nextRandomEventAt
      : null,
    pendingEventId:
      typeof value.pendingEventId === "string"
        ? value.pendingEventId
        : null,
    luckBoostCharges: Number.isFinite(value.luckBoostCharges)
      ? Math.max(0, Math.floor(value.luckBoostCharges))
      : 0,
    chainFlags: {
      labLetterStep: Number.isFinite(value.chainFlags?.labLetterStep)
        ? Math.max(-1, Math.min(3, Math.floor(value.chainFlags.labLetterStep)))
        : 0,
      zombieMemoryStep: Number.isFinite(value.chainFlags?.zombieMemoryStep)
        ? Math.max(-1, Math.min(3, Math.floor(value.chainFlags.zombieMemoryStep)))
        : 0
    }
  };
}

let eventState = normalizeEventState(saved.eventState);

/* =========================
   アイテム・周回
========================= */

function makeItemInstance(itemId, source = "unknown") {
  return {
    itemId,
    acquiredAt: Date.now(),
    source
  };
}

function normalizeItemId(value) {
  if (typeof value === "string") {
    if (itemDefs[value]) return value;
    return ITEM_NAME_TO_ID[value] || null;
  }

  if (value && typeof value === "object") {
    if (itemDefs[value.itemId]) return value.itemId;
    if (typeof value.name === "string") {
      return ITEM_NAME_TO_ID[value.name] || null;
    }
  }

  return null;
}

function normalizeLifeItems(value) {
  if (!Array.isArray(value)) return [];

  return value
    .map(item => {
      const itemId = normalizeItemId(item);
      if (!itemId) return null;

      return {
        itemId,
        acquiredAt:
          item && Number.isFinite(item.acquiredAt)
            ? item.acquiredAt
            : Date.now(),
        source:
          item && typeof item.source === "string"
            ? item.source
            : "legacy"
      };
    })
    .filter(Boolean);
}

function normalizeStoredItemIds(value) {
  if (!Array.isArray(value)) return [];

  return [
    ...new Set(
      value
        .map(normalizeItemId)
        .filter(Boolean)
    )
  ];
}


