function getV9DateKey() {
  const d = new Date();
  return [d.getFullYear(), String(d.getMonth()+1).padStart(2,'0'), String(d.getDate()).padStart(2,'0')].join('-');
}

function createEmptyV9State() {
  return {
    researchPoints: 0,
    facilities: { eventScanner: 0, itemAnalyzer: 0, storage: 0, nursery: 0 },
    labStorageItems: [],
    completedMissions: [],
    daily: { dateKey: getV9DateKey(), care: 0, event: 0, special: 0, claimed: [], allClaimed: false },
    hiddenResearch: [],
    researchLog: [],
    startBonusAvailable: false,
    startBonusChoice: null,
    totalFacilityUpgrades: 0
  };
}

function normalizeV9State(value) {
  const empty = createEmptyV9State();
  if (!value || typeof value !== 'object') return empty;
  const facilities = value.facilities && typeof value.facilities === 'object' ? value.facilities : {};
  return {
    researchPoints: Number.isFinite(value.researchPoints) ? Math.max(0, Math.floor(value.researchPoints)) : 0,
    facilities: {
      eventScanner: Math.max(0, Math.min(V9_FACILITY_MAX_LEVEL, Math.floor(facilities.eventScanner || 0))),
      itemAnalyzer: Math.max(0, Math.min(V9_FACILITY_MAX_LEVEL, Math.floor(facilities.itemAnalyzer || 0))),
      storage: Math.max(0, Math.min(V9_FACILITY_MAX_LEVEL, Math.floor(facilities.storage || 0))),
      nursery: Math.max(0, Math.min(V9_FACILITY_MAX_LEVEL, Math.floor(facilities.nursery || 0)))
    },
    labStorageItems: Array.isArray(value.labStorageItems) ? value.labStorageItems.filter(id => itemDefs[id]) : [],
    completedMissions: Array.isArray(value.completedMissions) ? [...new Set(value.completedMissions.filter(id => V9_MISSION_DEFS[id]))] : [],
    daily: normalizeV9Daily(value.daily),
    hiddenResearch: Array.isArray(value.hiddenResearch) ? [...new Set(value.hiddenResearch.filter(id => typeof id === 'string'))] : [],
    researchLog: Array.isArray(value.researchLog) ? value.researchLog.slice(-V9_RESEARCH_LOG_LIMIT) : [],
    startBonusAvailable: value.startBonusAvailable === true,
    startBonusChoice: typeof value.startBonusChoice === 'string' ? value.startBonusChoice : null,
    totalFacilityUpgrades: Number.isFinite(value.totalFacilityUpgrades) ? Math.max(0, Math.floor(value.totalFacilityUpgrades)) : 0
  };
}

function normalizeV9Daily(value) {
  const key = getV9DateKey();
  if (!value || typeof value !== 'object' || value.dateKey !== key) {
    return { dateKey: key, care: 0, event: 0, special: 0, claimed: [], allClaimed: false };
  }
  return {
    dateKey: key,
    care: Math.max(0, Math.floor(value.care || 0)),
    event: Math.max(0, Math.floor(value.event || 0)),
    special: Math.max(0, Math.floor(value.special || 0)),
    claimed: Array.isArray(value.claimed) ? [...new Set(value.claimed)] : [],
    allClaimed: value.allClaimed === true
  };
}


