const BUILT_IN_APPROVED_ASSETS = Object.keys(BUILT_IN_ASSET_OVERRIDES);

function createEmptyV12State() {
  return {
    saveSchema: 12,
    assetOverrides: { ...BUILT_IN_ASSET_OVERRIDES },
    approvedAssets: [...BUILT_IN_APPROVED_ASSETS],
    lastAssetEditAt: null
  };
}

function normalizeV12State(value) {
  const empty = createEmptyV12State();
  if (!value || typeof value !== "object") return empty;

  const assetOverrides = { ...BUILT_IN_ASSET_OVERRIDES };
  if (value.assetOverrides && typeof value.assetOverrides === "object") {
    Object.entries(value.assetOverrides).forEach(([id, url]) => {
      if (typeof id === "string" && typeof url === "string" && url.trim()) {
        assetOverrides[id] = url.trim();
      }
    });
  }

  const approvedAssets = [
    ...BUILT_IN_APPROVED_ASSETS,
    ...(Array.isArray(value.approvedAssets)
      ? value.approvedAssets.filter(id => typeof id === "string")
      : [])
  ];

  return {
    saveSchema: 12,
    assetOverrides,
    approvedAssets: [...new Set(approvedAssets)],
    lastAssetEditAt: Number.isFinite(value.lastAssetEditAt)
      ? value.lastAssetEditAt
      : null
  };
}


