const V13_FAST_STAGE_SECONDS = {
  baby: 10,
  child: 10,
  teen: 15,
  adult: 20,
  elder: 10
};

const V13_FINAL_CHECKS = [
  ["assets", "本番画像43枠を確認"],
  ["routes", "少年→大人→老年の主要分岐を確認"],
  ["death", "途中死亡・老衰を確認"],
  ["zombie", "ゾンビ第二人生と結末を確認"],
  ["items", "アイテム・持ち越し・合成を確認"],
  ["save", "セーブ・再読込・バックアップ復元を確認"],
  ["fullrun", "高速通しテストを1周完了"],
  ["release", "本番モード表示を確認"]
];

function createEmptyV13State() {
  return {
    saveSchema: 13,
    productionMode: false,
    fastLifeTest: false,
    decayMinutes: 20,
    zeroDeathMinutes: 120,
    completedFinalChecks: [],
    lastFullRunAt: null,
    lastBulkAssetImportAt: null
  };
}

function normalizeV13State(value) {
  const empty = createEmptyV13State();
  if (!value || typeof value !== "object") return empty;
  const allowedChecks = new Set(V13_FINAL_CHECKS.map(([id]) => id));
  const decayMinutes = [15, 20, 30].includes(Number(value.decayMinutes))
    ? Number(value.decayMinutes)
    : 20;
  const zeroDeathMinutes = [60, 120, 180].includes(Number(value.zeroDeathMinutes))
    ? Number(value.zeroDeathMinutes)
    : 120;
  return {
    saveSchema: 13,
    productionMode: value.productionMode === true,
    fastLifeTest: value.fastLifeTest === true,
    decayMinutes,
    zeroDeathMinutes,
    completedFinalChecks: Array.isArray(value.completedFinalChecks)
      ? [...new Set(value.completedFinalChecks.filter(id => allowedChecks.has(id)))]
      : [],
    lastFullRunAt: Number.isFinite(value.lastFullRunAt) ? value.lastFullRunAt : null,
    lastBulkAssetImportAt: Number.isFinite(value.lastBulkAssetImportAt) ? value.lastBulkAssetImportAt : null
  };
}

function getRuntimeStageDurationSeconds(stage) {
  if (metaProgress?.v13?.fastLifeTest && V13_FAST_STAGE_SECONDS[stage?.key]) {
    return V13_FAST_STAGE_SECONDS[stage.key];
  }
  return stage?.durationSeconds || 0;
}

function getRuntimeTotalLifeSeconds() {
  return aliveStages.reduce((sum, stage) => sum + getRuntimeStageDurationSeconds(stage), 0);
}

function getRuntimeDecayIntervalMs() {
  const minutes = metaProgress?.v13?.decayMinutes || 20;
  return Math.max(1, minutes) * 60 * 1000;
}

function getRuntimeZeroDeathMs() {
  const minutes = metaProgress?.v13?.zeroDeathMinutes || 120;
  return Math.max(1, minutes) * 60 * 1000;
}


