function shiftLifeTimersAfterTitlePause(pausedMs) {
  if (!Number.isFinite(pausedMs) || pausedMs <= 0) return;

  if (Number.isFinite(birthTime)) birthTime += pausedMs;
  if (Number.isFinite(lastDecay)) lastDecay += pausedMs;
  if (Number.isFinite(zeroStartTime)) zeroStartTime += pausedMs;

  if (Number.isFinite(eventState?.nextRandomEventAt)) {
    eventState.nextRandomEventAt += pausedMs;
  }

  if (Number.isFinite(zombieState?.startedAt)) {
    zombieState.startedAt += pausedMs;
  }

  if (Number.isFinite(zombieState?.lastDecay)) {
    zombieState.lastDecay += pausedMs;
  }
}

function closeTitleScreen() {
  if (!titleScreenOpen) return;

  const pausedMs = Date.now() - titleScreenOpenedAt;
  shiftLifeTimersAfterTitlePause(pausedMs);

  titleScreenOpen = false;
  saveGame();
  resumeDemonLaboCharacterMotion();
  switchDemonLaboBgm("game");

  if (titleScreenEl) {
    titleScreenEl.style.opacity = "0";
    titleScreenEl.style.transform = "scale(1.015)";
    titleScreenEl.style.pointerEvents = "none";

    setTimeout(() => {
      titleScreenEl?.remove();
      titleScreenEl = null;
      document.body.style.overflow = "";
      gameLoop();
    }, 320);
  } else {
    document.body.style.overflow = "";
    gameLoop();
  }
}


function openDemonLaboTitleFromEntry() {
  if (!entryGateOpen) return;
  entryGateOpen = false;

  // iPhone / iPad の音声再生許可は、この実タップで取得する。
  unlockDemonLaboAudio();
  switchDemonLaboBgm("title");

  if (!entryGateEl) return;
  entryGateEl.style.pointerEvents = "none";
  entryGateEl.style.opacity = "0";

  setTimeout(() => {
    entryGateEl?.remove();
    entryGateEl = null;
  }, 180);
}

