function reorderDemonLaboGameplayPanels() {
  const lowerStack = document.getElementById("demonLaboLowerStack");
  if (!lowerStack) return;

  const resultPanel = document.getElementById("v10LifeResultPanel");
  if (resultPanel && resultPanel.parentNode !== lowerStack) {
    lowerStack.appendChild(resultPanel);
  }

  const itemPanel = document.getElementById("gameItemPanel");
  const hintPanel = document.getElementById("gameBranchHintPanel");
  const special = document.getElementById("specialAction");
  const help = document.getElementById("demonLaboHelpPanel");
  const history = document.getElementById("demonLaboEventHistoryPanel");

  // アイテムを、お世話ボタンのすぐ下側へ寄せる。
  if (itemPanel) {
    if (special && special.parentNode === lowerStack) {
      special.insertAdjacentElement("afterend", itemPanel);
    } else {
      lowerStack.insertAdjacentElement("afterbegin", itemPanel);
    }
  }

  // 分岐ヒントはアイテムのすぐ下。答えではなく現在の段階に応じたヒントだけを出す。
  if (itemPanel && hintPanel) {
    itemPanel.insertAdjacentElement("afterend", hintPanel);
  } else if (hintPanel) {
    lowerStack.appendChild(hintPanel);
  }

  // 補助情報は分岐ヒントより下へ。
  if (hintPanel && history) {
    hintPanel.insertAdjacentElement("afterend", history);
  } else if (itemPanel && history) {
    itemPanel.insertAdjacentElement("afterend", history);
  } else if (history) {
    lowerStack.appendChild(history);
  }

  if (history && help) {
    history.insertAdjacentElement("afterend", help);
  } else if (help) {
    lowerStack.appendChild(help);
  }
}

