function eventHistoryStageLabel(entry) {
  if (!entry) return "不明";

  if (entry.stageKey === "teen" && entry.teenType) {
    return teenLabel(entry.teenType);
  }

  if (entry.stageKey === "adult" && entry.adultType) {
    return routeDisplayName(entry.adultType, "adult");
  }

  if (entry.stageKey === "elder" && entry.elderType) {
    return routeDisplayName(entry.elderType, "elder");
  }

  return aliveStages.find(stage => stage.key === entry.stageKey)?.name ||
    entry.stageKey ||
    "不明";
}

