function growthMeterCurrentLabel(stageKey) {
  if (stageKey === "teen" && teenType) return teenLabel(teenType);
  if (stageKey === "adult" && adultType) return routeDisplayName(adultType, "adult");
  if (stageKey === "elder" && elderType) return routeDisplayName(elderType, "elder");
  return aliveStages.find(stage => stage.key === stageKey)?.name || "";
}

function growthMeterNextLabel(stageInfo) {
  if (stageInfo.index >= aliveStages.length - 1) return "大往生";
  return aliveStages[stageInfo.index + 1]?.name || "次の成長";
}

function refreshDemonLaboGrowthMeter() {
  if (
    !demonLaboGrowthMeter ||
    !demonLaboGrowthLabel ||
    !demonLaboGrowthTime ||
    !demonLaboGrowthBar
  ) return;

  if (isDead || zombieState.active) {
    demonLaboGrowthMeter.style.display = "none";
    return;
  }

  demonLaboGrowthMeter.style.display = "block";

  const info = getCurrentStageInfo();
  const stageDuration = Math.max(1, info.stageEnd - info.stageStart);
  const elapsedInStage = Math.max(
    0,
    Math.min(stageDuration, info.elapsedSeconds - info.stageStart)
  );
  const remain = Math.max(0, info.stageEnd - info.elapsedSeconds);
  const progress = Math.max(
    0,
    Math.min(100, (elapsedInStage / stageDuration) * 100)
  );

  const currentLabel = growthMeterCurrentLabel(info.stage.key);
  const nextLabel = growthMeterNextLabel(info);

  demonLaboGrowthLabel.textContent =
    "🌸 " + currentLabel + " → " + nextLabel + " ✨";
  demonLaboGrowthTime.textContent =
    ((document.documentElement.classList.contains("dl-phone-app-layout") ||
      document.documentElement.classList.contains("dl-ipad-app-layout"))
      ? "次の成長まで "
      : "あと ") + formatTime(remain);
  demonLaboGrowthBar.style.width = progress.toFixed(2) + "%";
}

