function refreshDemonLaboCareHint() {
  if (!demonLaboCareHint) return;

  [feedButton, playButton, sleepButton, bathButton].forEach(button => {
    if (button) button.classList.remove("dl-care-target");
  });

  if (isDead || zombieState.active) {
    demonLaboCareHint.style.display = "none";
    return;
  }

  demonLaboCareHint.style.display = "block";

  if (isCareLockedByOperatorThunder()) {
    demonLaboCareHint.classList.remove("care-good", "care-watch", "care-danger");
    demonLaboCareHint.classList.add("care-danger");
    demonLaboCareHint.textContent =
      "⚡ 運営の雷ペナルティ中。お世話ボタン使用不可：あと " +
      formatTime(operatorThunderRemainingSeconds());
    return;
  }

  const needs = [
    { key: "hunger", value: hunger, label: "お腹", action: "ごはん", emoji: "🍚", button: feedButton },
    { key: "energy", value: energy, label: "体力", action: "寝る", emoji: "🌙", button: sleepButton },
    { key: "mood", value: mood, label: "機嫌", action: "遊ぶ", emoji: "🎲", button: playButton },
    { key: "clean", value: clean, label: "清潔", action: "お風呂", emoji: "🛁", button: bathButton }
  ].sort((a, b) => a.value - b.value);

  const lowest = needs[0];

  demonLaboCareHint.classList.remove("care-good", "care-watch", "care-danger");

  if (lowest.value <= 0) {
    demonLaboCareHint.classList.add("care-danger");

    let dangerText =
      "⚠️ 危険！ " + lowest.label + "が0。早めに「" + lowest.action + "」！";

    if (zeroStartTime !== null) {
      const deathAt = zeroStartTime + getRuntimeZeroDeathMs();
      const remaining = Math.max(
        0,
        Math.ceil((deathAt - Date.now()) / 1000)
      );

      dangerText =
        "⚠️ " + lowest.label + "が0！ このままだと残念まで " +
        formatTime(remaining) + "。";
    }

    demonLaboCareHint.textContent = dangerText;
    if (lowest.button) lowest.button.classList.add("dl-care-target");
    return;
  }

  if (lowest.value < 30) {
    demonLaboCareHint.classList.add("care-danger");
    demonLaboCareHint.textContent =
      lowest.emoji + " " + lowest.label + "がかなり減ってる。「" + lowest.action + "」がおすすめ。";
    if (lowest.button) lowest.button.classList.add("dl-care-target");
    return;
  }

  if (lowest.value < 50) {
    demonLaboCareHint.classList.add("care-watch");
    demonLaboCareHint.textContent =
      "そろそろ " + lowest.emoji + "「" + lowest.action + "」をしておくと安心。";
    if (lowest.button) lowest.button.classList.add("dl-care-target");
    return;
  }

  demonLaboCareHint.classList.add("care-good");
  demonLaboCareHint.textContent = "✨ 今は元気。好きなお世話をしてOK。";
}

