/* =========================
   基本処理
========================= */

function clamp(value) {
  return Math.max(0, Math.min(100, value));
}

const RESEARCH_LEVEL_THRESHOLDS = [0, 0, 15, 35, 60, 90, 130, 180, 240];

function getResearchLevel() {
  let level = 1;
  for (let i = 2; i < RESEARCH_LEVEL_THRESHOLDS.length; i++) {
    if (metaProgress.researchXp >= RESEARCH_LEVEL_THRESHOLDS[i]) {
      level = i;
    }
  }
  return Math.min(8, level);
}

function getResearchProgressText() {
  const level = getResearchLevel();
  if (level >= 8) {
    return "研究レベル8（MAX） / 研究XP " + metaProgress.researchXp;
  }
  const next = RESEARCH_LEVEL_THRESHOLDS[level + 1];
  return "研究レベル" + level + " / 研究XP " + metaProgress.researchXp + " / 次まで" + Math.max(0, next - metaProgress.researchXp);
}

function addResearchXp(amount) {
  if (!Number.isFinite(amount) || amount <= 0) return;
  const gained = Math.floor(amount);
  metaProgress.researchXp += gained;
  if (metaProgress.v9) {
    metaProgress.v9.researchPoints += Math.floor(gained / 5);
  }
}

function getGenerationBonusGuideText() {
  const g = metaProgress.generation;
  return [
    (g < 3 ? "▶ " : "") + "1〜2代目：初期ステータス80",
    (g >= 3 && g < 5 ? "▶ " : "") + "3〜4代目：初期ステータス85",
    (g >= 5 && g < 10 ? "▶ " : "") + "5〜9代目：初期ステータス90",
    (g >= 10 ? "▶ " : "") + "10代目以降：初期ステータス95"
  ].join("\n");
}

function getHiddenRouteHintText() {
  const level = getResearchLevel();
  const hints = [];
  if (level >= 2) hints.push("・でー問題児には、普通の育成だけでは固定できない進路がある。特定アイテムが鍵。 ");
  if (level >= 3) hints.push("・超レア2種と『記憶』は、死後のルートにも影響する。 ");
  if (level >= 4) hints.push("・封印された扉の記憶は少年期に再び反応する。 ");
  if (level >= 5) hints.push("・怪しい薬はニートでーもんだけでなく、危険な死に方にも関係する。 ");
  if (level >= 6) hints.push("・更生系アイテム同士の組み合わせには、単独使用とは違う結果がある。 ");
  return hints.length ? hints.join("\n") : "研究レベル2で最初の隠しルートヒントが解放される。";
}

function getEndingGuideText() {
  const level = getResearchLevel();
  return endingIds.map(id => {
    const def = endingDefs[id];
    const discovered = metaProgress.unlockedEndings.includes(id);
    if (discovered) {
      if (id === "awakened_return") return "✓ " + endingLabel(id) + "：覚醒ルート＋対応する老年専用行動2回以上";
      if (id === "redemption_legacy") return "✓ " + endingLabel(id) + "：更生の特殊組み合わせ＋普通の老年";
      return "✓ " + endingLabel(id) + "：" + adultLabel(def.route) + "老年で専用行動3回以上";
    }
    if (level < 3) return "？？？：研究レベル3で条件ヒント解放";
    if (def.hidden && level < 6) return "？？？：隠しエンディング。研究レベル6で追加ヒント";
    if (id === "awakened_return") return "？？？：覚醒したまま老年まで進み、専用行動を重ねる";
    if (id === "redemption_legacy") return "？？？：でー問題児の更生に関わる特殊な組み合わせが必要";
    return "？？？：" + adultLabel(def.route) + "の道を老年まで極める";
  }).join("\n");
}

function checkProgressionRewards() {
  const level = getResearchLevel();
  const researchRewards = [
    { id: "level2", level: 2, itemId: "research_ticket", message: "研究レベル2報酬：研究イベント券" },
    { id: "level4", level: 4, itemId: "lucky_coin", message: "研究レベル4報酬：幸運のコイン" },
    { id: "level6", level: 6, itemId: "mysterious_sample", message: "研究レベル6報酬：謎の研究サンプル" }
  ];

  researchRewards.forEach(reward => {
    if (level >= reward.level && !metaProgress.claimedResearchRewards.includes(reward.id)) {
      metaProgress.claimedResearchRewards.push(reward.id);
      acquireItem(reward.itemId, "research_level_reward", false);
      if (reward.level === 4) unlockSpecial("research_level_4");
      if (reward.level === 6) unlockSpecial("research_level_6");
    }
  });

  const percent = getOverallDiscoveryProgress().percent;
  const discoveryRewards = [
    { id: "25", percent: 25, xp: 5 },
    { id: "50", percent: 50, itemId: "research_ticket", xp: 10 },
    { id: "75", percent: 75, itemId: "mysterious_sample", xp: 15 },
    { id: "100", percent: 100, itemId: "research_badge", xp: 25 }
  ];

  discoveryRewards.forEach(reward => {
    if (percent >= reward.percent && !metaProgress.claimedDiscoveryRewards.includes(reward.id)) {
      metaProgress.claimedDiscoveryRewards.push(reward.id);
      if (reward.xp) addResearchXp(reward.xp);
      if (reward.itemId) acquireItem(reward.itemId, "discovery_reward", false);
      if (reward.percent === 75) unlockSpecial("discovery_75_reward");
    }
  });
  if (metaProgress.v9) v9CheckProgress();
}

function grantLifeEvaluationReward() {
  if (!isDead || routeFlags.lifeRewardGranted) return;
  routeFlags.lifeRewardGranted = true;
  const result = calculateLifeEvaluation();

  if (result.rank === "S") {
    acquireItem("gold_lab_medal", "life_rank_s", false);
    addResearchXp(20);
    showEventMessage("人生評価S報酬：金の研究メダル＋研究XP20！");
  } else if (result.rank === "A") {
    acquireItem("research_ticket", "life_rank_a", false);
    addResearchXp(12);
    showEventMessage("人生評価A報酬：研究イベント券＋研究XP12！");
  } else if (result.rank === "B") {
    acquireItem("lucky_coin", "life_rank_b", false);
    addResearchXp(6);
    showEventMessage("人生評価B報酬：幸運のコイン＋研究XP6！");
  } else {
    addResearchXp(result.rank === "C" ? 3 : 1);
  }
}

function grantSpecialEndingReward() {
  if (!specialEndingId || routeFlags.specialEndingRewardGranted) return;
  routeFlags.specialEndingRewardGranted = true;
  addResearchXp(15);
  if (specialEndingId === "awakened_return") {
    acquireItem("mysterious_sample", "special_ending", false);
  }
  if (specialEndingId === "redemption_legacy") {
    acquireItem("rehab_charm", "special_ending", false);
  }
}

function unlockAchievement(id) {
  if (!ACHIEVEMENT_DEFS[id]) return false;

  if (!metaProgress.unlockedAchievements.includes(id)) {
    metaProgress.unlockedAchievements.push(id);
    return true;
  }

  return false;
}

function getDiscoverableItemIds() {
  return Object.keys(itemDefs).filter(id => itemDefs[id]?.rewardOnly !== true);
}

function unlockEnding(id) {
  if (!endingDefs[id]) return false;
  if (!metaProgress.unlockedEndings.includes(id)) {
    metaProgress.unlockedEndings.push(id);
    addResearchXp(8);
    return true;
  }
  return false;
}

function getOverallDiscoveryProgress() {
  const eventIds = [...randomEventDefs, ...zombieEventDefs].map(event => event.id);
  const uniqueEventIds = [...new Set(eventIds)];

  const total =
    teenTypeIds.length +
    adultTypeIds.length +
    getDiscoverableItemIds().length +
    uniqueEventIds.length +
    zombieTypeIds.length +
    Object.keys(SPECIAL_UNLOCK_LABELS).length +
    Object.keys(recipeDefs).length +
    EVENT_CHAIN_IDS.length +
    endingIds.length;

  const found =
    metaProgress.unlockedTeenTypes.length +
    metaProgress.unlockedRoutes.length +
    getDiscoverableItemIds().filter(id => metaProgress.discoveredItems.includes(id)).length +
    uniqueEventIds.filter(id => metaProgress.discoveredEvents.includes(id)).length +
    metaProgress.unlockedZombieRoutes.length +
    metaProgress.specialUnlocks.filter(id => SPECIAL_UNLOCK_LABELS[id]).length +
    metaProgress.discoveredRecipes.filter(id => recipeDefs[id]).length +
    metaProgress.completedEventChains.filter(id => EVENT_CHAIN_IDS.includes(id)).length +
    metaProgress.unlockedEndings.filter(id => endingDefs[id]).length;

  return {
    found,
    total,
    percent: total ? Math.floor((found / total) * 100) : 0
  };
}

function checkAchievements() {
  if (metaProgress.unlockedTeenTypes.length >= 1) {
    unlockAchievement("first_teen_route");
  }

  if (teenTypeIds.every(id => metaProgress.unlockedTeenTypes.includes(id))) {
    unlockAchievement("all_teen_routes");
  }

  if (metaProgress.unlockedRoutes.length >= 1) {
    unlockAchievement("first_adult_route");
  }

  if (adultTypeIds.every(id => metaProgress.unlockedRoutes.includes(id))) {
    unlockAchievement("all_adult_routes");
  }

  if (metaProgress.discoveredItems.length >= 1) {
    unlockAchievement("first_item");
  }

  if (
    getDiscoverableItemIds().every(id =>
      metaProgress.discoveredItems.includes(id)
    )
  ) {
    unlockAchievement("all_items");
  }

  if (metaProgress.permanentItems.length >= 1) {
    unlockAchievement("first_super_item");
  }

  if (metaProgress.discoveredEvents.length >= 5) {
    unlockAchievement("event_five");
  }

  if (
    deathKind === "natural" ||
    metaProgress.lifeHistory.some(item => item.deathKind === "natural")
  ) {
    unlockAchievement("natural_life");
  }

  if (
    ["zombie", "zombie_phase", "zombie_end"].includes(deathKind) ||
    metaProgress.specialUnlocks.includes("zombie_route")
  ) {
    unlockAchievement("zombie_discovered");
  }

  if (metaProgress.specialUnlocks.includes("awakened_route")) {
    unlockAchievement("hidden_route_discovered");
  }

  const completedChoiceCount = eventState.history.filter(
    entry => typeof entry.choiceLabel === "string" && entry.choiceLabel
  ).length;

  if (completedChoiceCount >= 5) {
    unlockAchievement("choice_collector");
  }

  if (metaProgress.generation >= 3) {
    unlockAchievement("third_generation");
  }

  if (
    zombieState.active ||
    metaProgress.specialUnlocks.includes("zombie_second_life")
  ) {
    unlockAchievement("zombie_second_life");
  }

  if (metaProgress.unlockedZombieRoutes.length >= 1) {
    unlockAchievement("first_zombie_end");
  }

  if (zombieTypeIds.every(id => metaProgress.unlockedZombieRoutes.includes(id))) {
    unlockAchievement("all_zombie_ends");
  }

  if (metaProgress.unlockedZombieRoutes.includes("revived")) {
    unlockAchievement("revived_from_zombie");
  }

  if (metaProgress.discoveredRecipes.length >= 1) {
    unlockAchievement("first_craft");
  }

  if (Object.keys(recipeDefs).every(id => metaProgress.discoveredRecipes.includes(id))) {
    unlockAchievement("recipe_master");
  }

  if (metaProgress.completedEventChains.includes("lab_letter")) {
    unlockAchievement("lab_chain_complete");
  }

  if (metaProgress.completedEventChains.includes("zombie_memory")) {
    unlockAchievement("zombie_memory_chain");
  }

  if (metaProgress.unlockedEndings.length >= 1) {
    unlockAchievement("first_special_ending");
  }

  if (endingIds.every(id => metaProgress.unlockedEndings.includes(id))) {
    unlockAchievement("ending_master");
  }

  if (metaProgress.generation >= 5) {
    unlockAchievement("generation_five");
  }

  if (
    metaProgress.lifeHistory.some(item => item?.evaluation?.rank === "S") ||
    (isDead && calculateLifeEvaluation().rank === "S")
  ) {
    unlockAchievement("first_life_rank_s");
  }

  const overall = getOverallDiscoveryProgress();
  if (overall.percent >= 50) {
    unlockAchievement("discovery_half");
  }
  if (overall.percent >= 100) {
    unlockAchievement("discovery_complete");

    if (!metaProgress.permanentItems.includes("research_badge")) {
      metaProgress.permanentItems.push("research_badge");
    }
    if (!metaProgress.discoveredItems.includes("research_badge")) {
      metaProgress.discoveredItems.push("research_badge");
    }
    unlockAchievement("research_badge");
  }

  if (getResearchLevel() >= 4) unlockAchievement("research_level_4");
  if (getResearchLevel() >= 6) unlockAchievement("research_level_6");
  if (metaProgress.generation >= 10) unlockAchievement("generation_ten");
  if (metaProgress.unlockedEndings.length >= 5) unlockAchievement("ending_guide_master");
}

function saveGame() {
  if (isSageTimeActive()) {
    energy = 0;
    redMamushiActive = false;
  }
  if (redMamushiActive && energy < 50) {
    redMamushiActive = false;
  }

  checkAchievements();
  if (!metaProgress.v10) metaProgress.v10 = createEmptyV10State();

  const now = Date.now();
  metaProgress.v10.lastSaveAt = now;

  const payload = JSON.stringify({
    hunger,
    energy,
    mood,
    clean,

    birthTime,
    lastDecay,
    zeroStartTime,
    careLockUntil,
    sageTimeUntil,
    redMamushiActive,

    isDead,
    deathKind,
    deathStageKey,
    deathRouteType,
    specialEndingId,
    specialState,

    teenType,
    adultType,
    elderType,
    routeFlags,
    zombieState,

    careHistory,
    teenSpecialHistory,
    adultSpecialHistory,
    elderSpecialHistory,

    eventState,
    lifeItems,
    metaProgress
  });

  try {
    if (now - demonLaboLastAutoBackupAt >= 5 * 60 * 1000) {
      const previous = localStorage.getItem(SAVE_KEY);
      if (previous) {
        localStorage.setItem(AUTOBACKUP_KEY, previous);
      }
      demonLaboLastAutoBackupAt = now;
    }

    localStorage.setItem(SAVE_KEY, payload);
    refreshDemonLaboSaveStatus(now, false);
  } catch (error) {
    refreshDemonLaboSaveStatus(now, true);

    if (metaProgress?.v11?.errorLog) {
      metaProgress.v11.errorLog.push({
        time: now,
        message: "セーブ失敗：" + String(error?.message || error)
      });
      metaProgress.v11.errorLog =
        metaProgress.v11.errorLog.slice(-50);
    }
  }
}
function anyStatZero() {
  return hunger <= 0 || energy <= 0 || mood <= 0 || clean <= 0;
}

/* =========================
   成長段階取得
========================= */

function getStageInfoAt(time) {
  const elapsedSeconds = Math.max(
    0,
    Math.floor((time - birthTime) / 1000)
  );

  let accumulated = 0;

  for (let i = 0; i < aliveStages.length; i++) {
    const stage = aliveStages[i];
    const end = accumulated + getRuntimeStageDurationSeconds(stage);

    if (elapsedSeconds < end) {
      return {
        index: i,
        stage,
        elapsedSeconds,
        stageStart: accumulated,
        stageEnd: end
      };
    }

    accumulated = end;
  }

  const lastIndex = aliveStages.length - 1;

  return {
    index: lastIndex,
    stage: aliveStages[lastIndex],
    elapsedSeconds,
    stageStart:
      getRuntimeTotalLifeSeconds() - getRuntimeStageDurationSeconds(aliveStages[lastIndex]),
    stageEnd: getRuntimeTotalLifeSeconds()
  };
}

function getCurrentStageInfo() {
  return getStageInfoAt(Date.now());
}

function addCareHistory(action, time = Date.now()) {
  const key = getStageInfoAt(time).stage.key;

  if (!careHistory[key]) {
    careHistory[key] = createEmptyStageHistory();
  }

  careHistory[key][action] += 1;
}

/* =========================
   少年タイプ判定
========================= */

function predictTeenTypeFromHistory(childHistory, personalityBias = null) {
  const child = childHistory || createEmptyStageHistory();
  const bias = normalizePersonalityBias(personalityBias);

  if ((child.danger || 0) + bias.trouble >= 2) return "trouble";
  if ((child.play || 0) + bias.party >= 3) return "party";
  if (
    (
      (child.feed || 0) >= 2 &&
      (child.sleep || 0) >= 2 &&
      (child.bath || 0) >= 2
    ) ||
    bias.honest >= 2
  ) return "honest";
  return "introvert";
}

function determineTeenType() {
  if (demonLaboBaseTeenPreview) return;
  if (teenType !== null) return;

  teenType = predictTeenTypeFromHistory(
    careHistory.child,
    routeFlags.personalityBias
  );

  unlockTeenType(teenType);
  saveGame();
}

/* =========================
   大人予測・判定
========================= */

function predictAdultType(type = teenType) {
  if (routeFlags.usedSuspiciousDrug) {
    return "fallen";
  }

  if (routeFlags.forcedAdultType) {
    return routeFlags.forcedAdultType;
  }

  const teen = careHistory.teen;
  const special = teenSpecialHistory[type] ?? 0;

  if (type === "honest") {
    return "normal";
  }

  if (teen.danger >= 3) {
    return "fallen";
  }

  if (type === "trouble") {
    if (
      special >= 3 &&
      teen.sleep >= 2 &&
      teen.bath >= 2
    ) {
      return "fighter";
    }

    if (special >= 3 && teen.play >= 3) {
      return "yakuza";
    }

    if (
      teen.feed >= 2 &&
      teen.sleep >= 2 &&
      teen.bath >= 2 &&
      special <= 2
    ) {
      return "normal";
    }

    return "fallen";
  }

  if (type === "party") {
    if (special >= 3 && teen.bath >= 3) {
      return "host";
    }

    if (special >= 3 && teen.play >= 3) {
      return "rockstar";
    }

    if (
      teen.feed >= 2 &&
      teen.sleep >= 2 &&
      teen.bath >= 2 &&
      special <= 2
    ) {
      return "normal";
    }

    return "fallen";
  }

  if (type === "introvert") {
    if (special >= 3 && teen.play >= 3) {
      return "gambler";
    }

    if (special >= 3 && teen.play <= 2) {
      return "otaku";
    }

    if (
      teen.feed >= 2 &&
      teen.sleep >= 2 &&
      teen.bath >= 2 &&
      special <= 2
    ) {
      return "normal";
    }

    return "fallen";
  }

  return "normal";
}

function determineAdultType() {
  if (adultType !== null) return;

  determineTeenType();
  adultType = predictAdultType(teenType);
  unlockRoute(adultType);
  saveGame();
}

/* =========================
   老年予測・判定
========================= */

function predictElderType(type = adultType) {
  const adult = careHistory.adult;
  const special = adultSpecialHistory[type] ?? 0;

  if (adult.danger >= 3) {
    return "fallen";
  }

  if (type === "fallen") {
    if (
      adult.feed >= 3 &&
      adult.sleep >= 3 &&
      adult.bath >= 3 &&
      adult.danger <= 1
    ) {
      return "normal";
    }

    return "fallen";
  }

  if (type === "normal") {
    return "normal";
  }

  if (special >= 3) {
    return type;
  }

  if (
    adult.feed >= 2 &&
    adult.sleep >= 2 &&
    adult.bath >= 2
  ) {
    return "normal";
  }

  return type;
}

function determineElderType() {
  if (elderType !== null) return;

  determineAdultType();
  elderType = predictElderType(adultType);
  unlockRoute(elderType);
  saveGame();
}

function checkGrowthTypes() {
  const key = getCurrentStageInfo().stage.key;

  if (demonLaboBaseTeenPreview && key === "teen") {
    return;
  }

  if (["teen", "adult", "elder"].includes(key)) {
    determineTeenType();
  }

  if (["adult", "elder"].includes(key)) {
    determineAdultType();
  }

  if (key === "elder") {
    determineElderType();
  }
}

