function createEventMessageArea() {
  if (eventMessageEl) return;

  eventMessageEl = document.createElement("div");
  eventMessageEl.id = "eventMessage";
  eventMessageEl.style.margin = "10px auto";
  eventMessageEl.style.padding = "8px";
  eventMessageEl.style.maxWidth = "520px";
  eventMessageEl.style.textAlign = "center";
  eventMessageEl.style.fontWeight = "bold";
  eventMessageEl.style.display = "none";

  nextStageText.insertAdjacentElement("afterend", eventMessageEl);
}

function createEventChoiceArea() {
  if (eventChoiceEl) return;

  eventChoiceEl = document.createElement("div");
  eventChoiceEl.id = "eventChoiceArea";
  eventChoiceEl.style.margin = "8px auto 12px";
  eventChoiceEl.style.padding = "8px";
  eventChoiceEl.style.maxWidth = "520px";
  eventChoiceEl.style.textAlign = "center";
  eventChoiceEl.style.display = "none";

  eventMessageEl.insertAdjacentElement("afterend", eventChoiceEl);
}

function showEventMessage(message) {
  if (!eventMessageEl) {
    createEventMessageArea();
  }

  const important = v10IsImportantMessage(message);
  eventMessageEl.textContent = important ? "★ " + message : message;
  eventMessageEl.style.display = "block";
  eventMessageEl.style.border = important ? "2px solid currentColor" : "1px solid rgba(0,0,0,0.18)";
  eventMessageEl.style.borderRadius = "10px";
  eventMessageEl.style.boxShadow = important ? "0 3px 12px rgba(0,0,0,0.18)" : "none";
  eventMessageEl.style.fontSize = important ? "1.05em" : "1em";

  v10PushNotification(message, important);
  refreshV10NotificationPanel();
}

function unlockTeenType(typeId) {
  if (!typeId || !teenTypeDefs[typeId]) return;

  if (!metaProgress.unlockedTeenTypes.includes(typeId)) {
    metaProgress.unlockedTeenTypes.push(typeId);
    addResearchXp(2);
  }
}

function discoverItem(itemId) {
  if (!itemDefs[itemId]) return;
  if (!metaProgress.discoveredItems.includes(itemId)) {
    metaProgress.discoveredItems.push(itemId);
    addResearchXp(2);
  }
}

function discoverEvent(eventId) {
  if (!eventId) return;
  if (!metaProgress.discoveredEvents.includes(eventId)) {
    metaProgress.discoveredEvents.push(eventId);
    addResearchXp(1);
  }
}

function unlockSpecial(id) {
  if (!id) return;
  if (!metaProgress.specialUnlocks.includes(id)) {
    metaProgress.specialUnlocks.push(id);
    addResearchXp(4);
  }
}

function recordGameEvent(id, message, details = {}) {
  const info = getCurrentStageInfo();

  eventState.total += 1;
  eventState.lastEventId = id;
  discoverEvent(id);

  eventState.history.push({
    id,
    message,
    choiceLabel:
      typeof details.choiceLabel === "string"
        ? details.choiceLabel
        : null,
    resultText:
      typeof details.resultText === "string"
        ? details.resultText
        : null,
    time: Date.now(),
    stageKey: info.stage.key,
    teenType,
    adultType,
    elderType,
    awakenedRoute: routeFlags.awakenedRoute === true
  });

  if (eventState.history.length > EVENT_LOG_LIMIT) {
    eventState.history = eventState.history.slice(-EVENT_LOG_LIMIT);
  }

  v9IncrementDaily("event");
  showEventMessage(message);
  saveGame();
  refreshInfoPanel();
  refreshProgressPanel();
  refreshDemonLaboEventHistoryPanel();
  refreshDemonLaboQuickHud();
}

function randomEventDelay() {
  const level = getResearchLevel();
  const speedMultiplier = Math.max(0.72, 1 - (level - 1) * 0.04);
  const base =
    RANDOM_EVENT_MIN_MS +
    Math.random() * (RANDOM_EVENT_MAX_MS - RANDOM_EVENT_MIN_MS);
  const facilityLevel = metaProgress.v9?.facilities?.eventScanner || 0;
  const facilityMultiplier = Math.max(0.85, 1 - facilityLevel * 0.05);
  return Math.floor(base * speedMultiplier * facilityMultiplier);
}

function scheduleNextRandomEvent() {
  eventState.nextRandomEventAt = Date.now() + randomEventDelay();
  saveGame();
}

function pickRandom(list) {
  return list[Math.floor(Math.random() * list.length)];
}

function weightedRandomItemId(rarity = null) {
  const byRarity = {
    normal: [
      "rice_ball",
      "toy",
      "adult_toy",
      "love_doll",
      "red_mamushi",
      "bath_salt",
      "soft_pillow",
      "adachi_brother",
      "minami_king",
      "orin",
      "potenico"
    ],
    rare: [
      "lucky_coin",
      "suspicious_drug",
      "rehab_charm",
      "old_guitar_pick",
      "research_ticket",
      "quick_finish_secret",
      "hair_tonic"
    ],
    super: ["mysterious_key", "strange_fragment", "mysterious_sample"]
  };

  let chosenRarity = rarity;

  if (!chosenRarity) {
    const boosted = (eventState.luckBoostCharges || 0) > 0;
    const roll = Math.random() * 100;

    const analyzerLevel = metaProgress.v9?.facilities?.itemAnalyzer || 0;
    if (boosted) {
      eventState.luckBoostCharges -= 1;
      const superLine = 8 + analyzerLevel * 2;
      const rareLine = 55 + analyzerLevel * 4;
      if (roll < superLine) {
        chosenRarity = "super";
      } else if (roll < rareLine) {
        chosenRarity = "rare";
      } else {
        chosenRarity = "normal";
      }
    } else {
      const superLine = 2 + analyzerLevel * 2;
      const rareLine = 20 + analyzerLevel * 5;
      if (roll < superLine) {
        chosenRarity = "super";
      } else if (roll < rareLine) {
        chosenRarity = "rare";
      } else {
        chosenRarity = "normal";
      }
    }
  }

  return pickRandom(byRarity[chosenRarity]);
}

function acquireItem(itemId, source = "event", announce = true) {
  const def = itemDefs[itemId];
  if (!def) return null;

  discoverItem(itemId);

  if (def.rarity === "super") {
    if (!metaProgress.permanentItems.includes(itemId)) {
      metaProgress.permanentItems.push(itemId);
    }
  } else {
    lifeItems.push(makeItemInstance(itemId, source));
  }

  v10ShowFlash(
    "🎁 " + def.label + " GET！【" +
      ITEM_RARITY_LABELS[def.rarity] + "】"
  );

  if (announce) {
    showEventMessage(
      "「" + def.label + "」を手に入れた！【" +
        ITEM_RARITY_LABELS[def.rarity] + "】"
    );
  }

  saveGame();
  refreshItemPanel();
  refreshInfoPanel();

  return itemId;
}

function selectRareCarry(itemId) {
  const def = itemDefs[itemId];

  if (!def || def.rarity !== "rare") {
    return;
  }

  const owned = lifeItems.some(item => item.itemId === itemId);

  if (!owned) {
    showEventMessage("そのレアアイテムは今の人生では所持していない。");
    return;
  }

  const ok = confirm(
    "「" + def.label + "」を次の人生への持ち越しアイテムにしますか？\n持ち越せるレアアイテムは1個です。"
  );

  if (!ok) return;

  metaProgress.rareCarryItems = [itemId].slice(0, MAX_RARE_CARRY);

  showEventMessage(
    "次の人生への持ち越しを「" + def.label + "」に設定した。"
  );

  saveGame();
  refreshItemPanel();
  refreshInfoPanel();
}

function useLifeItem(index) {
  if (isDead) return;

  const item = lifeItems[index];
  if (!item) return;

  const def = itemDefs[item.itemId];
  if (!def) return;

  if (def.consumable === false || typeof def.use !== "function") {
    showEventMessage("「" + def.label + "」は直接使うアイテムではない。");
    return;
  }

  const importantRouteItems = new Set([
    "suspicious_drug",
    "rehab_charm",
    "old_guitar_pick",
    "training_gloves",
    "underworld_card",
    "silver_card",
    "limited_figure",
    "lucky_dice",
    "rebirth_capsule"
  ]);

  if (importantRouteItems.has(item.itemId)) {
    const ok = confirm(
      "「" + def.label + "」を使いますか？\n\n" +
      "このアイテムは人生の進路や特殊な変化に影響する可能性があります。"
    );
    if (!ok) return;
  }

  demonLaboSageRecoveryBlocked = false;
  const used = def.use();

  if (used === false) {
    return;
  }

  const sageRecoveryWasBlocked = demonLaboSageRecoveryBlocked;
  demonLaboSageRecoveryBlocked = false;

  lifeItems.splice(index, 1);

  if (
    metaProgress.rareCarryItems.includes(item.itemId) &&
    !lifeItems.some(owned => owned.itemId === item.itemId)
  ) {
    metaProgress.rareCarryItems = metaProgress.rareCarryItems.filter(
      id => id !== item.itemId
    );
  }

  if (![
    "suspicious_drug",
    "hair_tonic",
    "quick_finish_secret",
    "adult_toy",
    "love_doll",
    "red_mamushi"
  ].includes(item.itemId)) {
    showEventMessage("「" + def.label + "」を使った。" );
  }

  if (sageRecoveryWasBlocked) {
    showEventMessage("賢者タイム中のため体力は回復しなかった。");
  }

  syncZeroTimer();
  saveGame();
  updateStatus();
  updateView();
  refreshItemPanel();
  focusDemonLaboCharacterAfterItemUse();
}

function hasPermanentItem(itemId) {
  return metaProgress.permanentItems.includes(itemId);
}

function hasLifeItem(itemId) {
  return lifeItems.some(item => item.itemId === itemId);
}

function consumeOneLifeItemById(itemId) {
  const index = lifeItems.findIndex(item => item.itemId === itemId);
  if (index < 0) return false;

  lifeItems.splice(index, 1);

  if (
    metaProgress.rareCarryItems.includes(itemId) &&
    !lifeItems.some(item => item.itemId === itemId)
  ) {
    metaProgress.rareCarryItems = metaProgress.rareCarryItems.filter(
      id => id !== itemId
    );
  }

  return true;
}

function countLifeItem(itemId) {
  return lifeItems.filter(item => item.itemId === itemId).length;
}

function isCareLockedByOperatorThunder() {
  return Number.isFinite(careLockUntil) && careLockUntil > Date.now();
}

function operatorThunderRemainingSeconds() {
  if (!isCareLockedByOperatorThunder()) return 0;
  return Math.max(0, Math.ceil((careLockUntil - Date.now()) / 1000));
}

function refreshOperatorThunderLock() {
  if (isDead || zombieState.active) return;

  const locked = isCareLockedByOperatorThunder();
  const buttons = [feedButton, playButton, sleepButton, bathButton];
  buttons.forEach(button => {
    if (!button) return;
    button.disabled = locked;
    button.title = locked
      ? "運営の雷：あと" + formatTime(operatorThunderRemainingSeconds())
      : "";
  });
}

function triggerOperatorThunderPickup() {
  discoverItem("operator_thunder");

  const alreadyLocked = isCareLockedByOperatorThunder();
  if (!alreadyLocked) {
    careLockUntil = Date.now() + OPERATOR_THUNDER_LOCK_MS;
  }

  refreshOperatorThunderLock();
  v10ShowFlash("⚡ 運営の雷！");
  saveGame();

  return alreadyLocked
    ? "また運営の雷が落ちた！ すでにペナルティ中なので残り時間は増えなかった。"
    : "運営の雷を拾ってしまった！ 全てのお世話ボタンが1時間使用不可になった。";
}

function tryAdachiBrotherRescue(deathTime = Date.now()) {
  if (!hasLifeItem("adachi_brother")) return false;

  consumeOneLifeItemById("adachi_brother");

  if (hunger <= 0) hunger = 20;
  if (energy <= 0) energy = 20;
  if (mood <= 0) mood = 20;
  if (clean <= 0) clean = 20;
  zeroStartTime = null;

  const stageKey = getStageInfoAt(deathTime).stage.key;
  v10ShowFlash("😎 足立のアニキ参上！");
  recordGameEvent(
    "adachi_brother_rescue",
    "途中死亡寸前に足立のアニキが助けに来た！ 「足立のアニキ」を1個消費して復活した。",
    { stageKey }
  );
  refreshItemPanel();
  return true;
}

function getLifeDecayRates() {
  return {
    hunger: hasLifeItem("potenico") ? 0.5 : 1,
    energy: hasLifeItem("orin") ? 0.5 : 1,
    mood: hasLifeItem("minami_king") ? 0.5 : 1,
    clean: 1
  };
}

function canCraftRecipe(recipeId) {
  const recipe = recipeDefs[recipeId];
  if (!recipe) return false;

  const needed = {};
  recipe.ingredients.forEach(id => {
    needed[id] = (needed[id] || 0) + 1;
  });

  return Object.entries(needed).every(([id, count]) =>
    countLifeItem(id) >= count
  );
}

function craftRecipe(recipeId) {
  const recipe = recipeDefs[recipeId];
  if (!recipe) return false;

  if (!canCraftRecipe(recipeId)) {
    showEventMessage("合成素材が足りない。");
    return false;
  }

  recipe.ingredients.forEach(id => {
    consumeOneLifeItemById(id);
  });

  acquireItem(recipe.result, "craft", false);

  if (!metaProgress.discoveredRecipes.includes(recipeId)) {
    metaProgress.discoveredRecipes.push(recipeId);
    addResearchXp(3);
  }

  recordGameEvent(
    "craft_" + recipeId,
    "アイテムを合成して「" + itemDefs[recipe.result].label + "」を作った。"
  );

  showEventMessage("「" + itemDefs[recipe.result].label + "」の合成に成功した！");
  saveGame();
  refreshItemPanel();
  refreshProgressPanel();
  refreshInfoPanel();
  return true;
}

