function createAdultRouteEvents() {
  return adultTypeIds.map(typeId => ({
    id: "adult_route_" + typeId,
    label: adultLabel(typeId) + "の転機",
    weight: 5,
    canTrigger() {
      return getCurrentStageInfo().stage.key === "adult" && adultType === typeId;
    },
    text: adultLabel(typeId) + "として、この先の生き方を考える出来事が起きた。",
    choices: [
      {
        label: "今の道を極める",
        apply() {
          adultSpecialHistory[typeId] = (adultSpecialHistory[typeId] || 0) + 1;
          mood = clamp(mood + 10);
          energy = clamp(energy - 10);
          elderType = null;
          return "今の生き方をさらに深めた。専用行動1回分として記録された。";
        }
      },
      {
        label: "生活を整える",
        apply() {
          careHistory.adult.feed += 1;
          careHistory.adult.sleep += 1;
          careHistory.adult.bath += 1;
          hunger = clamp(hunger + 5);
          recoverEnergy(5);
          clean = clamp(clean + 5);
          elderType = null;
          return "生活を立て直した。ごはん・寝る・風呂が各1回分として記録された。";
        }
      }
    ]
  }));
}

