function findEventDef(id) {
  return (
    randomEventDefs.find(event => event.id === id) ||
    zombieEventDefs.find(event => event.id === id) ||
    null
  );
}

function eventLabel(id) {
  const specialLabels = {
    used_suspicious_drug: "怪しい薬を使用",
    used_rehab_charm: "更生のお守りを使用",
    used_old_guitar_pick: "古びたギターピックを使用",
    used_training_gloves: "トレーニンググローブを使用",
    used_underworld_card: "裏社会の名刺を使用",
    used_silver_card: "きらびやかな名刺を使用",
    used_limited_figure: "限定フィギュアを使用",
    used_lucky_dice: "勝負師のダイスを使用",
    adachi_brother_rescue: "足立のアニキが途中死亡を回避",
    awakened_route_entered: "覚醒ルート",
    drug_zombie_awakening: "怪しい薬由来のでーもんゾンビ",
    zombie_awakening: "でーもんゾンビ",
    zombie_second_life_started: "でーもんゾンビ生活開始",
    zombie_second_life_finished: "でーもんゾンビの結末",
    craft_picnic_set: "アイテム合成：ピクニックセット",
    craft_relax_set: "アイテム合成：おやすみセット",
    craft_recovery_wrap: "アイテム合成：回復バンド"
  };

  return (
    specialLabels[id] ||
    findEventDef(id)?.label ||
    id
  );
}

function pickWeightedEvent() {
  const pool = zombieState.active ? zombieEventDefs : randomEventDefs;

  const available = pool.filter(
    event => !event.canTrigger || event.canTrigger()
  );

  if (!available.length) return null;

  const totalWeight = available.reduce(
    (sum, event) => sum + (event.weight || 1),
    0
  );

  let roll = Math.random() * totalWeight;

  for (const event of available) {
    roll -= event.weight || 1;
    if (roll <= 0) return event;
  }

  return available[available.length - 1];
}

function presentEventChoice(event) {
  if (!eventChoiceEl) createEventChoiceArea();

  eventState.pendingEventId = event.id;
  discoverEvent(event.id);
  showEventMessage(event.text);

  eventChoiceEl.innerHTML = "";
  eventChoiceEl.style.display = "block";

  event.choices.forEach((choice, index) => {
    const button = document.createElement("button");
    button.textContent = choice.label;
    button.style.margin = "4px";
    button.addEventListener("click", () => {
      resolveEventChoice(event.id, index);
    });
    eventChoiceEl.appendChild(button);
  });

  saveGame();
  refreshInfoPanel();

  setTimeout(() => {
    if (eventChoiceEl && eventChoiceEl.style.display !== "none") {
      eventChoiceEl.scrollIntoView({
        behavior: "smooth",
        block: "center",
        inline: "nearest"
      });
    }
  }, 80);
}

function resolveEventChoice(eventId, choiceIndex) {
  const event = findEventDef(eventId);
  const choice = event?.choices?.[choiceIndex];
  if (!event || !choice) return;

  const result = choice.apply?.();
  const message = result
    ? event.text + " " + result
    : event.text;

  eventState.pendingEventId = null;

  if (eventChoiceEl) {
    eventChoiceEl.innerHTML = "";
    eventChoiceEl.style.display = "none";
  }

  recordGameEvent(event.id, message, {
    choiceLabel: choice.label,
    resultText: typeof result === "string" ? result : ""
  });
  syncZeroTimer();
  scheduleNextRandomEvent();
  updateStatus();
  updateView();
  refreshItemPanel();
}

function restorePendingEventChoice() {
  if (!eventState.pendingEventId) return;

  const event = findEventDef(eventState.pendingEventId);

  if (!event || !event.choices) {
    eventState.pendingEventId = null;
    saveGame();
    return;
  }

  presentEventChoice(event);
}

function triggerRandomEvent(forceId = null) {
  if (isDead || eventState.pendingEventId) return;

  const event = forceId
    ? findEventDef(forceId)
    : pickWeightedEvent();

  if (!event) return;

  if (event.choices?.length) {
    presentEventChoice(event);
    return;
  }

  const extra = event.apply?.();
  const message = extra ? event.text + " " + extra : event.text;

  recordGameEvent(event.id, message);
  syncZeroTimer();
  scheduleNextRandomEvent();
  updateStatus();
  updateView();
  refreshItemPanel();
}

function checkRandomEvent() {
  if (isDead || eventState.pendingEventId) return;

  if (!Number.isFinite(eventState.nextRandomEventAt)) {
    scheduleNextRandomEvent();
    return;
  }

  if (Date.now() >= eventState.nextRandomEventAt) {
    triggerRandomEvent();
  }
}

function unlockRoute(typeId) {
  if (!typeId || !adultTypeDefs[typeId]) return;

  if (!metaProgress.unlockedRoutes.includes(typeId)) {
    metaProgress.unlockedRoutes.push(typeId);
    addResearchXp(3);
    saveGame();
  }
}

function unlockZombieRoute(typeId) {
  if (!typeId || !zombieTypeDefs[typeId]) return;

  if (!metaProgress.unlockedZombieRoutes.includes(typeId)) {
    metaProgress.unlockedZombieRoutes.push(typeId);
    addResearchXp(5);
  }

  if (typeId === "sentient") unlockSpecial("zombie_sentient");
  if (typeId === "feral") unlockSpecial("zombie_feral");
  if (typeId === "wanderer") unlockSpecial("zombie_wanderer");
  if (typeId === "revived") unlockSpecial("zombie_revived");

  saveGame();
}

