function setBarStatus(bar, value) {
  bar.classList.remove(
    "status-normal",
    "status-warning",
    "status-danger"
  );

  if (value >= 60) {
    bar.classList.add("status-normal");
  } else if (value >= 30) {
    bar.classList.add("status-warning");
  } else {
    bar.classList.add("status-danger");
  }

  bar.style.width = value + "%";
}

function updateStatus() {
  syncDemonLaboAdultJokeStates({ announceSageEnd: true });

  hungerEl.textContent = hunger;
  energyEl.textContent = energy;
  moodEl.textContent = mood;
  cleanEl.textContent = clean;

  setBarStatus(hungerBar, hunger);
  setBarStatus(energyBar, energy);
  setBarStatus(moodBar, mood);
  setBarStatus(cleanBar, clean);

  refreshDemonLaboCareHint();
  refreshDemonLaboGrowthMeter();
  refreshDemonLaboLifeTimer();
  refreshDemonLaboThought();
  refreshDemonLaboQuickHud();
  syncDemonLaboCuteParameterUI();
  syncDemonLaboVitalityDisplay();
  refreshDemonLaboSageTimeTimer();
  saveGame();
  refreshInfoPanel();
}

/* =========================
   時間表示
========================= */

function formatTime(seconds) {
  seconds = Math.max(0, Math.floor(seconds));

  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const secs = seconds % 60;

  if (hours > 0) {
    return hours + "時間" + minutes + "分";
  }

  if (minutes > 0) {
    return minutes + "分" + secs + "秒";
  }

  return secs + "秒";
}

