function useSpecialAction() {
  if (isDead) return;

  const key = getCurrentStageInfo().stage.key;
  let usedActionLabel = "";
  let usedActionCount = 0;

  if (key === "teen") {
    determineTeenType();

    const action = teenSpecialActions[teenType];
    if (!action) return;

    action.use();
    teenSpecialHistory[teenType] += 1;
    usedActionLabel = action.label;
    usedActionCount = teenSpecialHistory[teenType];
  } else if (key === "adult") {
    determineAdultType();

    const action = adultSpecialActions[adultType];
    if (!action) return;

    action.use();
    adultSpecialHistory[adultType] += 1;
    elderType = null;
    usedActionLabel = action.label;
    usedActionCount = adultSpecialHistory[adultType];
  } else if (key === "elder") {
    determineElderType();

    const action = elderSpecialActions[elderType];
    if (!action) return;

    action.use();
    elderSpecialHistory[elderType] += 1;
    usedActionLabel = action.label;
    usedActionCount = elderSpecialHistory[elderType];
  } else {
    return;
  }

  showDemonLaboActionFeedback(
    "✨ " + usedActionLabel,
    "専用行動 " + usedActionCount + "回目"
  );

  syncZeroTimer();
  updateStatus();
  updateView();
}

