/* =========================
   死亡処理
========================= */

function getRouteTypeForStage(stageKey) {
  if (stageKey === "teen") return teenType;
  if (stageKey === "adult") return adultType;
  if (stageKey === "elder") return elderType;
  return null;
}

function getMidDeathMotionSlot(stageKey, routeType) {
  if (stageKey === "teen" && routeType) {
    return "death:route_common";
  }

  if (["adult", "elder"].includes(stageKey)) {
    const adultRoute = normalizeAdultTypeId(routeType);
    if (adultRoute && adultRoute !== "normal") {
      return "death:route_common";
    }
  }

  return "death:" + stageKey;
}

function getMidDeathImage(stageKey, routeType) {
  if (stageKey === "teen" && routeType) {
    return teenDeathTypeImages[routeType] || deathStages.teen.image;
  }

  if (stageKey === "adult" && routeType) {
    return adultDeathTypeImages[routeType] || deathStages.adult.image;
  }

  if (stageKey === "elder" && routeType) {
    return elderDeathTypeImages[routeType] || deathStages.elder.image;
  }

  return deathStages[stageKey]?.image || naturalDeathStage.image;
}

function getZombieReason(deathTime = Date.now()) {
  if (routeFlags.specialDeathSeed === true) {
    return "fragment_seed";
  }

  const stageInfo = getStageInfoAt(deathTime);
  const stageKey = stageInfo.stage.key;
  const stageHistory = careHistory[stageKey];
  const routeType = getRouteTypeForStage(stageKey);

  if (
    routeFlags.usedSuspiciousDrug &&
    ["adult", "elder"].includes(stageKey) &&
    routeType === "fallen" &&
    (stageHistory?.danger || 0) >= 2
  ) {
    return "drug_fallen_danger";
  }

  return null;
}

function shouldZombieTransform(deathTime = Date.now()) {
  return getZombieReason(deathTime) !== null;
}

function triggerZombieDeath(deathTime) {
  const stageInfo = getStageInfoAt(deathTime);
  const zombieReason = getZombieReason(deathTime) || "test_or_forced";
  const originRoute = getRouteTypeForStage(stageInfo.stage.key);
  const now = Date.now();

  isDead = false;
  deathKind = "zombie_phase";
  deathStageKey = stageInfo.stage.key;
  deathRouteType = originRoute;
  specialEndingId = null;
  specialState = "zombie";
  routeFlags.zombieReason = zombieReason;

  zombieState = {
    active: true,
    startedAt: now,
    lastDecay: now,
    originStage: stageInfo.stage.key,
    originRoute,
    finalType: null,
    endedAt: null,
    actions: {
      feed: 0,
      roam: 0,
      rest: 0,
      remember: 0
    }
  };

  hunger = 65;
  energy = 60;
  mood = 45;
  clean = 30;
  zeroStartTime = null;
  lastDecay = now;

  unlockSpecial("zombie_route");
  unlockSpecial("zombie_second_life");
  scheduleNextRandomEvent();
  eventState.pendingEventId = null;

  if (eventChoiceEl) {
    eventChoiceEl.innerHTML = "";
    eventChoiceEl.style.display = "none";
  }

  if (zombieReason === "drug_fallen_danger") {
    unlockSpecial("drug_zombie_condition");
    recordGameEvent(
      "drug_zombie_awakening",
      "怪しい薬の影響と危険状態が重なった。命が尽きたあと、ゾンビとして再び動き出した。ここから第二の人生が始まる。"
    );
  } else {
    recordGameEvent(
      "zombie_second_life_started",
      "命が尽きたはずだった。しかし再び動き出した。ゾンビとして第二の人生が始まった。"
    );
  }

  v10ShowFlash("🧟 でーもんゾンビ！");
  showEventMessage("命が尽きたはずなのに……でーもんゾンビとして動き出した。");

  saveGame();
}

