function getHairOvergrowthBaseImage() {
  const stageKey = deathStageKey || getCurrentStageInfo().stage.key;
  const routeType = deathRouteType || getRouteTypeForStage(stageKey);

  if (stageKey === "teen") {
    return teenTypeImages[routeType || teenType] ||
      aliveStages.find(stage => stage.key === "teen")?.image ||
      "";
  }

  if (stageKey === "adult") {
    const id = normalizeAdultTypeId(routeType || adultType) || "normal";
    return adultTypeImages[id] ||
      aliveStages.find(stage => stage.key === "adult")?.image ||
      "";
  }

  if (stageKey === "elder") {
    const id = normalizeAdultTypeId(routeType || elderType || adultType) || "normal";
    return elderTypeImages[id] ||
      aliveStages.find(stage => stage.key === "elder")?.image ||
      "";
  }

  return aliveStages.find(stage => stage.key === stageKey)?.image ||
    currentCharacterStaticUrl ||
    "";
}

