/* =========================
   人生履歴
========================= */

function saveLifeSummary() {
  if (!isDead) return;

  metaProgress.lifeHistory.push({
    generation: metaProgress.generation,
    finishedAt: Date.now(),
    deathKind,
    deathStageKey,
    specialState,
    teenType,
    adultType,
    elderType,
    finalRoute: normalizeAdultTypeId(deathRouteType) || null,
    specialEndingId,
    evaluation: calculateLifeEvaluation(),
    researchLevelAtEnd: getResearchLevel(),
    researchXpAtEnd: metaProgress.researchXp,
    zombieFinalType: zombieState.finalType || null,
    zombieActions: { ...zombieState.actions },
    eventHighlights: eventState.history.slice(-10).map(entry => ({
      id: entry.id,
      choiceLabel: entry.choiceLabel || null,
      resultText: entry.resultText || null,
      message: entry.message || ""
    })),
    specialFlags: {
      hiddenGrowthAwakened: routeFlags.hiddenGrowthAwakened === true,
      awakenedRoute: routeFlags.awakenedRoute === true,
      usedSuspiciousDrug: routeFlags.usedSuspiciousDrug === true,
      redemptionCombo: routeFlags.redemptionCombo === true,
      zombieReason: routeFlags.zombieReason || null
    }
  });

  if (metaProgress.lifeHistory.length > LIFE_HISTORY_LIMIT) {
    metaProgress.lifeHistory = metaProgress.lifeHistory.slice(
      -LIFE_HISTORY_LIMIT
    );
  }
}

/* =========================
   人生だけリセット
========================= */

function getGenerationStartStat(generation = metaProgress.generation) {
  if (generation >= 10) return 95;
  if (generation >= 5) return 90;
  if (generation >= 3) return 85;
  return 80;
}

function getGenerationBonusText() {
  const stat = getGenerationStartStat();
  return stat > 80
    ? metaProgress.generation + "代目ボーナス：初期ステータス" + stat
    : "周回ボーナス：まだなし（3代目から開始）";
}

function resetCurrentLife({ increaseGeneration = false } = {}) {
  resetDemonLaboMilestoneWatch();

  const carryIds = increaseGeneration
    ? metaProgress.rareCarryItems.slice(0, MAX_RARE_CARRY)
    : [];

  const carryLabels = carryIds
    .map(itemId => itemDefs[itemId]?.label || itemId)
    .filter(Boolean);

  if (increaseGeneration && isDead) {
    saveLifeSummary();
    metaProgress.generation += 1;
  }

  if (increaseGeneration) {
    metaProgress.rareCarryItems = [];
    if (metaProgress.v9) {
      metaProgress.v9.startBonusAvailable = true;
      metaProgress.v9.startBonusChoice = null;
    }
  }

  lifeItems = carryIds.map(itemId =>
    makeItemInstance(itemId, "carry_over")
  );

  const generationStartStat = getGenerationStartStat(metaProgress.generation);
  hunger = generationStartStat;
  energy = generationStartStat;
  mood = generationStartStat;
  clean = generationStartStat;

  birthTime = Date.now();
  lastDecay = Date.now();
  zeroStartTime = null;
  careLockUntil = 0;
  sageTimeUntil = 0;
  redMamushiActive = false;

  isDead = false;
  deathKind = null;
  deathStageKey = null;
  deathRouteType = null;
  specialEndingId = null;
  specialState = null;
  zombieState = createEmptyZombieState();

  teenType = null;
  adultType = null;
  elderType = null;

  routeFlags = {
    forcedAdultType: null,
    usedSuspiciousDrug: false,
    hiddenGrowthSeed: false,
    hiddenGrowthAwakened: false,
    awakenedRoute: false,
    redemptionCombo: false,
    specialDeathSeed: false,
    zombieReason: null,
    zombieCureBoost: false,
    lifeRewardGranted: false,
    specialEndingRewardGranted: false,
    timeShortcutUsedStages: [],
    personalityBias: normalizePersonalityBias(null)
  };

  careHistory = createEmptyCareHistory();

  teenSpecialHistory = Object.fromEntries(
    teenTypeIds.map(id => [id, 0])
  );

  adultSpecialHistory = Object.fromEntries(
    adultTypeIds.map(id => [id, 0])
  );

  elderSpecialHistory = Object.fromEntries(
    adultTypeIds.map(id => [id, 0])
  );

  eventState = createEmptyEventState();
  scheduleNextRandomEvent();

  if (eventMessageEl) {
    eventMessageEl.style.display = "none";
  }

  if (eventChoiceEl) {
    eventChoiceEl.innerHTML = "";
    eventChoiceEl.style.display = "none";
  }

  saveGame();
  updateStatus();
  updateView();
  refreshItemPanel();

  if (increaseGeneration) {
    v10ShowFlash("🌱 " + metaProgress.generation + "代目スタート！");
  }

  if (increaseGeneration && carryLabels.length) {
    showEventMessage(
      "前の人生から「" + carryLabels.join(" / ") + "」を持ち越した。"
    );
  }
}

restartButton.addEventListener("click", () => {
  if (!isDead) {
    const ok = confirm(
      "まだ人生の途中です。\n\n今の人生を終了して、新しい人生を始めますか？"
    );
    if (!ok) return;
  }

  const ownedRareIds = [
    ...new Set(
      lifeItems
        .filter(item => itemDefs[item.itemId]?.rarity === "rare")
        .map(item => item.itemId)
    )
  ];

  if (isDead && metaProgress.rareCarryItems.length) {
    const carryName = metaProgress.rareCarryItems
      .map(id => itemDefs[id]?.label || id)
      .join(" / ");

    const ok = confirm(
      "次の人生へ「" + carryName + "」を持ち越します。よろしいですか？"
    );

    if (!ok) return;
  } else if (isDead && ownedRareIds.length) {
    const ok = confirm(
      "レアアイテムを持っていますが、持ち越し指定されていません。\nこのまま次の人生へ進みますか？"
    );

    if (!ok) return;
  }

  resetCurrentLife({ increaseGeneration: true });
});

