/* =========================
   3段階 分岐ヒント

   Lv.1 = 初見向け。方向だけ匂わせる
   Lv.2 = 途中死亡などの失敗、または周回進行で具体化
   Lv.3 = 複数回の失敗・周回後。かなり分かりやすくする
========================= */

function getBranchHintLevel() {
  const history = Array.isArray(metaProgress?.lifeHistory)
    ? metaProgress.lifeHistory
    : [];

  const pastFailureCount = history.filter(item =>
    ["mid", "hair_overgrowth"].includes(item?.deathKind)
  ).length;
  const currentFailureCount =
    isDead && ["mid", "hair_overgrowth"].includes(deathKind) ? 1 : 0;
  const failureCount = pastFailureCount + currentFailureCount;

  if (failureCount >= 2 || history.length >= 4) return 3;
  if (failureCount >= 1 || history.length >= 2) return 2;
  return 1;
}

function getBranchHintProgressText(level = getBranchHintLevel()) {
  if (level >= 3) {
    return "ヒントLv.3 / 3　かなり具体的なヒントまで解放済み";
  }
  if (level === 2) {
    return "ヒントLv.2 / 3　少し具体的なヒントが解放済み";
  }
  return "ヒントLv.1 / 3　まずは薄いヒントから";
}

