function refreshItemPanel() {
  if (!itemPanelEl) return;

  const wasOpen = itemPanelEl.open;
  itemPanelEl.innerHTML = "";

  const summary = document.createElement("summary");
  summary.textContent = "🎒 アイテム（" + lifeItems.length + "）";
  summary.style.cursor = "pointer";
  summary.style.fontWeight = "bold";
  itemPanelEl.appendChild(summary);

  const guide = document.createElement("div");
  guide.className = "dl-item-note";
  guide.textContent =
    "アイテム名を見ただけで効果が分からないものは、ここに説明が出る。レア以上の進路系アイテムは、答えを全部バラさずヒント表示にしている。";
  itemPanelEl.appendChild(guide);

  const carrySummary = document.createElement("div");
  carrySummary.className = "dl-item-note";
  carrySummary.textContent =
    "次の人生への持ち越し指定：" +
    (metaProgress.rareCarryItems.length
      ? metaProgress.rareCarryItems
          .map(id => itemDefs[id]?.label || id)
          .join(" / ")
      : "なし");
  itemPanelEl.appendChild(carrySummary);

  const currentTitle = document.createElement("div");
  currentTitle.className = "dl-item-section-title";
  currentTitle.textContent = "今の人生のアイテム";
  itemPanelEl.appendChild(currentTitle);

  if (!lifeItems.length) {
    const empty = document.createElement("div");
    empty.className = "dl-item-note";
    empty.textContent = "まだアイテムを持っていない。";
    itemPanelEl.appendChild(empty);
  } else {
    const groupedItems = [];
    const groupedMap = new Map();

    lifeItems.forEach(item => {
      if (!itemDefs[item.itemId]) return;

      if (!groupedMap.has(item.itemId)) {
        const group = { itemId: item.itemId, count: 0 };
        groupedMap.set(item.itemId, group);
        groupedItems.push(group);
      }

      groupedMap.get(item.itemId).count += 1;
    });

    groupedItems.forEach(group => {
      const def = itemDefs[group.itemId];
      if (!def) return;

      const card = document.createElement("div");
      card.className = "dl-item-card";

      const head = document.createElement("div");
      head.className = "dl-item-head";

      const rarity = document.createElement("span");
      rarity.className = "dl-item-rarity " + def.rarity;
      rarity.textContent = ITEM_RARITY_LABELS[def.rarity];

      const name = document.createElement("span");
      name.className = "dl-item-name";
      name.textContent = def.label;

      const count = document.createElement("span");
      count.className = "dl-item-count";
      count.textContent = "×" + group.count;

      head.appendChild(rarity);
      head.appendChild(name);
      head.appendChild(count);
      card.appendChild(head);

      const desc = document.createElement("div");
      desc.className = "dl-item-description";
      desc.textContent = itemPublicDescription(group.itemId);
      card.appendChild(desc);

      const conditionText = itemUseConditionText(group.itemId);
      if (conditionText) {
        const condition = document.createElement("div");
        condition.className = "dl-item-condition";
        condition.textContent = conditionText;
        card.appendChild(condition);
      }

      const actions = document.createElement("div");
      actions.className = "dl-item-actions";

      if (def.consumable !== false && typeof def.use === "function") {
        const useButton = document.createElement("button");

        const stageLocked =
          ["hair_tonic", "adult_toy", "love_doll", "red_mamushi"].includes(group.itemId) &&
          (
            isDead ||
            zombieState.active ||
            !["adult", "elder"].includes(getCurrentStageInfo().stage.key)
          );

        useButton.textContent = stageLocked ? "大人から使用可" : "使う";
        useButton.disabled = stageLocked;

        useButton.addEventListener("click", () => {
          const currentIndex = lifeItems.findIndex(
            owned => owned.itemId === group.itemId
          );
          if (currentIndex >= 0) useLifeItem(currentIndex);
        });
        actions.appendChild(useButton);
      } else {
        const owned = document.createElement("span");
        owned.className = "dl-item-condition";
        owned.textContent = "所持効果";
        actions.appendChild(owned);
      }

      if (def.rarity === "rare") {
        const carryButton = document.createElement("button");
        const selected = metaProgress.rareCarryItems.includes(group.itemId);
        carryButton.textContent = selected
          ? "持ち越し指定中"
          : "次の人生へ持ち越す";
        carryButton.disabled = selected;
        carryButton.addEventListener("click", () =>
          selectRareCarry(group.itemId)
        );
        actions.appendChild(carryButton);
      }

      card.appendChild(actions);
      itemPanelEl.appendChild(card);
    });
  }

  const craftTitle = document.createElement("div");
  craftTitle.className = "dl-item-section-title";
  craftTitle.textContent = "🧪 アイテム合成";
  itemPanelEl.appendChild(craftTitle);

  Object.entries(recipeDefs).forEach(([recipeId, recipe]) => {
    const row = document.createElement("div");
    row.className = "dl-craft-row";

    const ingredientText = recipe.ingredients
      .map(id => itemDefs[id]?.label || id)
      .join(" ＋ ");

    const discovered = metaProgress.discoveredRecipes.includes(recipeId);

    const text = document.createElement("div");
    text.textContent =
      (discovered ? "✓ " + recipe.label : "？？？") +
      "　素材：" + ingredientText;
    row.appendChild(text);

    if (discovered && itemDefs[recipe.result]) {
      const desc = document.createElement("div");
      desc.className = "dl-item-description";
      desc.textContent = itemPublicDescription(recipe.result);
      row.appendChild(desc);
    }

    const button = document.createElement("button");
    button.textContent = canCraftRecipe(recipeId)
      ? "合成する"
      : "素材不足";
    button.disabled = !canCraftRecipe(recipeId);
    button.style.marginTop = "6px";
    button.addEventListener("click", () => craftRecipe(recipeId));
    row.appendChild(button);

    itemPanelEl.appendChild(row);
  });

  const permanentTitle = document.createElement("div");
  permanentTitle.className = "dl-item-section-title";
  permanentTitle.textContent = "✨ 超レア・永続所持";
  itemPanelEl.appendChild(permanentTitle);

  if (!metaProgress.permanentItems.length) {
    const empty = document.createElement("div");
    empty.className = "dl-item-note";
    empty.textContent = "まだ持っていない。";
    itemPanelEl.appendChild(empty);
  } else {
    metaProgress.permanentItems.forEach(id => {
      const def = itemDefs[id];
      const row = document.createElement("div");
      row.className = "dl-permanent-row";

      const title = document.createElement("div");
      title.className = "dl-item-name";
      title.textContent = def?.label || id;
      row.appendChild(title);

      const desc = document.createElement("div");
      desc.className = "dl-item-description";
      desc.textContent = itemPublicDescription(id);
      row.appendChild(desc);

      itemPanelEl.appendChild(row);
    });
  }

  itemPanelEl.open = wasOpen;
}

