  progressPanelEl.appendChild(progressBox);

  const rewardBox = document.createElement("div");
  rewardBox.style.whiteSpace = "pre-wrap";
  rewardBox.style.margin = "12px 0";
  rewardBox.textContent =
    "【研究報酬】\n" +
    "Lv2：研究イベント券 / Lv4：幸運のコイン / Lv6：謎の研究サンプル\n" +
    "図鑑25％：研究XP / 50％：研究イベント券 / 75％：謎の研究サンプル / 100％：研究者バッジ\n" +
    "人生評価S：金の研究メダル＋研究XP20";
  progressPanelEl.appendChild(rewardBox);

  const hintTitle = document.createElement("div");
  hintTitle.textContent = "【隠しルートヒント】";
  hintTitle.style.fontWeight = "bold";
  hintTitle.style.margin = "14px 0 6px";
  progressPanelEl.appendChild(hintTitle);

  const hintText = document.createElement("div");
  hintText.style.whiteSpace = "pre-wrap";
  hintText.textContent = getHiddenRouteHintText();
  progressPanelEl.appendChild(hintText);

  const endingTitle = document.createElement("div");
  endingTitle.textContent = "【発見済みエンディング】";
