function v10IsImportantMessage(message) {
  return /ゾンビ|特殊エンディング|エンディング|覚醒|死亡|育毛|GAME OVER|人間へ帰還|超レア|研究レベル|人生評価S|図鑑100|研究者バッジ/.test(String(message || ""));
}

function v10PushNotification(message, important = false) {
  if (!metaProgress.v10) metaProgress.v10 = createEmptyV10State();
  const list = metaProgress.v10.notifications;
  const now = Date.now();
  const last = list[list.length - 1];

  if (last && last.message === message && now - last.time < 1200) {
    return;
  }

  list.push({ time: now, message: String(message), important: important === true });
  if (list.length > V10_NOTIFICATION_LIMIT) {
    metaProgress.v10.notifications = list.slice(-V10_NOTIFICATION_LIMIT);
  }
}

function v10CurrentStageLabel() {
  if (zombieState.active) return "でーもんゾンビ";
  if (isDead) {
    if (deathKind === "hair_overgrowth") return "育毛成功しすぎ";
    if (deathKind === "zombie_end") return "でーもんゾンビ";
    if (deathKind === "natural") return "大往生";
    if (deathKind === "zombie") return "でーもんゾンビ";
    return "残念";
  }

  const key = getCurrentStageInfo().stage.key;
  if (key === "teen") return teenType ? teenLabel(teenType) : "でーもん少年";
  if (key === "adult") return adultType ? routeDisplayName(adultType, "adult") : "でーもん";
  if (key === "elder") return elderType ? routeDisplayName(elderType, "elder") : "ジジィでーもん";
  return aliveStages.find(stage => stage.key === key)?.name || key;
}

function v10RouteTrailText() {
  const parts = ["ベビーでーもん", "でーちゃん"];
  if (teenType) parts.push(teenLabel(teenType));
  if (adultType) parts.push(adultLabel(adultType));
  if (elderType) parts.push(elderLabel(elderType));

  if (zombieState.active || deathKind === "zombie_end" || deathKind === "zombie") {
    parts.push("でーもんゾンビ");
  }

  if (deathKind === "hair_overgrowth") {
    parts.push("育毛成功しすぎ");
  }

  return parts.join(" 〉 ");
}

function v10SaveStatusText() {
  const ts = metaProgress.v10?.lastSaveAt;
  if (!Number.isFinite(ts)) return "自動保存：準備中";
  return "自動保存：" + new Date(ts).toLocaleTimeString("ja-JP", { hour: "2-digit", minute: "2-digit", second: "2-digit" }) + " 保存済み";
}

function v10ResearchEffectSummary() {
  const f = metaProgress.v9?.facilities || {};
  const scanner = f.eventScanner || 0;
  const analyzer = f.itemAnalyzer || 0;
  const storage = f.storage || 0;
  const nursery = f.nursery || 0;
  const eventShorten = scanner * 5;
  const superBoost = analyzer * 2;
  const rareBoost = analyzer * 5;
  const startBonus = 5 + nursery * 5;

  return [
    "イベント観測装置：発生待ち時間 約" + eventShorten + "％短縮",
    "アイテム解析装置：超レア率 +" + superBoost + "pt / レア以上判定 +" + rareBoost + "pt",
    "特殊保管庫：" + storage + "枠",
    "育成支援室：周回開始ボーナス +" + startBonus
  ].join("\n");
}

