function v10EnhanceTestPanel() {
  const panel = document.querySelector("#gameTestPanel");
  if (!panel || panel.querySelector("#v10TestSearch")) return;

  const search = document.createElement("input");
  search.id = "v10TestSearch";
  search.type = "search";
  search.placeholder = "テスト項目を検索 例：ゾンビ / 研究 / 大人";
  search.style.width = "calc(100% - 16px)";
  search.style.margin = "10px 4px";
  search.style.padding = "8px";

  const reset = document.createElement("button");
  reset.textContent = "検索解除";
  reset.style.margin = "0 4px 10px";

  const summary = panel.querySelector("summary");
  summary.insertAdjacentElement("afterend", reset);
  reset.insertAdjacentElement("afterend", search);

  const apply = () => {
    const q = search.value.trim().toLowerCase();
    Array.from(panel.children).forEach(el => {
      if (el === summary || el === search || el === reset) return;
      if (!q) {
        el.style.display = "";
        return;
      }
      el.style.display = (el.textContent || "").toLowerCase().includes(q) ? "" : "none";
    });
  };

  search.addEventListener("input", apply);
  reset.addEventListener("click", () => {
    search.value = "";
    apply();
  });
}

function v10RefreshAll() {
  refreshV10Dashboard();
  refreshV10NotificationPanel();
  refreshV10CompendiumPanel();
  refreshV10ResultPanel();
}


/* =========================
   v1.7 完成仕上げ・本番準備
========================= */

let v11CompletionPanelEl = null;
let v11ReportTextareaEl = null;
let v11ReleaseButtonEl = null;

function v11Hours(seconds) {
  const hours = seconds / 3600;
  return Number.isInteger(hours) ? String(hours) : hours.toFixed(1);
}

function v11TotalNormalCareActions() {
  return aliveStages.reduce((sum, stage) => {
    const h = careHistory[stage.key] || {};
    return sum + (h.feed || 0) + (h.play || 0) + (h.sleep || 0) + (h.bath || 0);
  }, 0);
}

function v11TotalSpecialActions() {
  const teenTotal = Object.values(teenSpecialHistory || {}).reduce((a, b) => a + (b || 0), 0);
  const adultTotal = Object.values(adultSpecialHistory || {}).reduce((a, b) => a + (b || 0), 0);
  const elderTotal = Object.values(elderSpecialHistory || {}).reduce((a, b) => a + (b || 0), 0);
  const zombieTotal = zombieState?.actions
    ? Object.values(zombieState.actions).reduce((a, b) => a + (Number.isFinite(b) ? b : 0), 0)
    : 0;
  return teenTotal + adultTotal + elderTotal + zombieTotal;
}

function v11CollectPlaceholderAssets() {
  const missing = [];
  const add = (category, label) => missing.push({ category, label });

  adultTypeIds.filter(id => id !== "normal").forEach(id => {
    if (!adultTypeImages[id] || adultTypeImages[id] === defaultAdultImage) {
      add("大人", adultLabel(id));
    }
  });

  adultTypeIds.filter(id => id !== "normal").forEach(id => {
    if (!elderTypeImages[id] || elderTypeImages[id] === defaultElderImage) {
      add("老年", elderLabel(id));
    }
  });

  adultTypeIds.filter(id => id !== "normal").forEach(id => {
    if (!corpseTypeImages[id] || corpseTypeImages[id] === naturalDeathStage.image) {
      add("老衰後", elderLabel(id) + " → 大往生");
    }
  });

  teenTypeIds.forEach(id => {
    if (!teenDeathTypeImages[id] || teenDeathTypeImages[id] === deathStages.teen.image) {
      add("途中死亡", teenLabel(id));
    }
  });

  adultTypeIds.filter(id => id !== "normal").forEach(id => {
    if (!adultDeathTypeImages[id] || adultDeathTypeImages[id] === deathStages.adult.image) {
      add("途中死亡", adultLabel(id) + "大人");
    }
  });

  adultTypeIds.filter(id => id !== "normal").forEach(id => {
    if (!elderDeathTypeImages[id] || elderDeathTypeImages[id] === deathStages.elder.image) {
      add("途中死亡", elderLabel(id));
    }
  });

  zombieTypeIds.forEach(id => {
    if (!zombieTypeImages[id]) {
      add("ゾンビ", zombieLabel(id));
    }
  });

  return missing;
}

function v11RunIntegrityAudit({ saveResult = true } = {}) {
  const errors = [];
  const warnings = [];

  const assert = (condition, message) => {
    if (!condition) errors.push(message);
  };

  assert(aliveStages.length === 5, "成長段階が5段階ではない");
  assert(TOTAL_LIFE_SECONDS === 60 * 60 * 60, "通常人生の合計時間が60時間ではない");

  teenTypeIds.forEach(id => {
    assert(Boolean(teenTypeDefs[id]?.label), "少年タイプの表示名不足: " + id);
    assert(Boolean(teenTypeImages[id]), "少年画像不足: " + id);
    assert(Boolean(teenSpecialActions[id]?.use), "少年専用行動不足: " + id);
  });

  adultTypeIds.forEach(id => {
    assert(Boolean(adultTypeDefs[id]?.label), "大人タイプの表示名不足: " + id);
    assert(Boolean(adultSpecialActions[id]?.use), "大人専用行動不足: " + id);
    assert(Boolean(elderSpecialActions[id]?.use), "老年専用行動不足: " + id);
    assert(Boolean(adultTypeImages[id]), "大人画像マップ不足: " + id);
    assert(Boolean(elderTypeImages[id]), "老年画像マップ不足: " + id);
    assert(Boolean(corpseTypeImages[id]), "屍画像マップ不足: " + id);
  });

  Object.entries(itemDefs).forEach(([id, def]) => {
    assert(Boolean(def?.label), "アイテム表示名不足: " + id);
    assert(["normal", "rare", "super"].includes(def?.rarity), "アイテムレア度異常: " + id);
    assert(typeof def?.use === "function", "アイテム使用処理不足: " + id);
  });

  Object.entries(recipeDefs).forEach(([id, recipe]) => {
    assert(Boolean(itemDefs[recipe?.result]), "合成結果アイテムが存在しない: " + id);
    assert(Array.isArray(recipe?.ingredients) && recipe.ingredients.length >= 2, "合成素材不足: " + id);
    (recipe?.ingredients || []).forEach(itemId => {
      assert(Boolean(itemDefs[itemId]), "存在しない合成素材: " + id + " → " + itemId);
    });
  });

  Object.entries(endingDefs).forEach(([id, def]) => {
    assert(Boolean(def?.label), "エンディング表示名不足: " + id);
    if (def?.route) assert(Boolean(adultTypeDefs[def.route]), "エンディングのルート参照異常: " + id);
  });

  const eventIds = [...randomEventDefs, ...zombieEventDefs].map(event => event?.id).filter(Boolean);
  const duplicatedEvents = eventIds.filter((id, index) => eventIds.indexOf(id) !== index);
  assert(duplicatedEvents.length === 0, "イベントID重複: " + [...new Set(duplicatedEvents)].join(", "));

  const placeholderAssets = v11CollectPlaceholderAssets();
  if (placeholderAssets.length) {
    warnings.push("本番画像の未差し替え候補が " + placeholderAssets.length + " 枠ある");
  }

  if (TEST_MODE) warnings.push("TEST_MODE が ON");
  if (!metaProgress.lifeHistory.length) warnings.push("完走した人生履歴がまだない");

  const result = {
    time: Date.now(),
    errors,
    warnings,
    placeholderAssets
  };

  if (saveResult) {
    metaProgress.v11.lastAudit = {
      time: result.time,
      errorCount: errors.length,
      warningCount: warnings.length
    };
    saveGame();
  }

  return result;
}

function v11PlaytestStatusText() {
  const done = new Set(metaProgress.v11.completedPlaytestChecks || []);
  return V11_PLAYTEST_CHECKS
    .map(([id, label]) => (done.has(id) ? "✅ " : "⬜ ") + label)
    .join("\n");
}

function v11BuildReportText() {
  const audit = v11RunIntegrityAudit({ saveResult: false });
  const placeholdersByCategory = {};
  audit.placeholderAssets.forEach(item => {
    placeholdersByCategory[item.category] = (placeholdersByCategory[item.category] || 0) + 1;
  });

  const currentInfo = zombieState.active
    ? "ゾンビ第二人生"
    : isDead
      ? "人生終了"
      : getCurrentStageInfo().stage.name;

  const lastErrors = metaProgress.v11.errorLog.length
    ? metaProgress.v11.errorLog
        .slice(-5)
        .map(entry => "・" + new Date(entry.time).toLocaleString() + " " + entry.message)
        .join("\n")
    : "なし";

  return [
    GAME_TITLE + " v" + GAME_VERSION + " 本番準備レポート",
    "作成日時: " + new Date().toLocaleString(),
    "セーブスキーマ: " + (metaProgress.v12?.saveSchema || metaProgress.v11.saveSchema),
    "現在: " + currentInfo,
    "世代: " + metaProgress.generation + "代目",
    "ルート: " + v10RouteTrailText(),
    "",
    "【自動整合性チェック】",
    "エラー: " + audit.errors.length,
    "警告: " + audit.warnings.length,
    audit.errors.length ? audit.errors.map(x => "× " + x).join("\n") : "重大エラーなし",
    audit.warnings.length ? audit.warnings.map(x => "△ " + x).join("\n") : "警告なし",
    "",
    "【本番画像】",
    "未差し替え候補: " + audit.placeholderAssets.length + "枠",
    Object.entries(placeholdersByCategory).length
      ? Object.entries(placeholdersByCategory).map(([k, v]) => k + ": " + v + "枠").join(" / ")
      : "仮画像なし",
    "",
    "【バランス設定】",
    "ベビーでーもん " + v11Hours(aliveStages[0].durationSeconds) + "時間 / でーちゃん " + v11Hours(aliveStages[1].durationSeconds) + "時間 / でーもん少年 " + v11Hours(aliveStages[2].durationSeconds) + "時間 / でーもん " + v11Hours(aliveStages[3].durationSeconds) + "時間 / ジジィでーもん " + v11Hours(aliveStages[4].durationSeconds) + "時間",
    "通常人生 合計 " + v11Hours(TOTAL_LIFE_SECONDS) + "時間（2日半）",
    "ステータス減少間隔 " + Math.round(DECAY_INTERVAL_MS / 60000) + "分",
    "0状態から死亡まで " + v11Hours(ZERO_DEATH_MS / 1000) + "時間",
    "ランダムイベント " + Math.round(RANDOM_EVENT_MIN_MS / 60000) + "〜" + Math.round(RANDOM_EVENT_MAX_MS / 60000) + "分",
    "ゾンビ第二人生 " + v11Hours(ZOMBIE_PHASE_DURATION_SECONDS) + "時間",
    "",
    "【現在人生のテスト量】",
    "通常育成行動: " + v11TotalNormalCareActions() + "回",
    "専用行動: " + v11TotalSpecialActions() + "回",
    "イベント: " + (eventState.total || 0) + "回",
    "所持アイテム: " + lifeItems.length + "個",
    "",
    "【手動プレイテスト】",
    v11PlaytestStatusText(),
    "",
    "【直近のJavaScriptエラー】",
    lastErrors
  ].join("\n");
}

function v11CreateSafetySnapshot() {
  try {
    saveGame();
    const raw = localStorage.getItem(SAVE_KEY);
    if (!raw) throw new Error("現在のセーブデータが見つからない");
    localStorage.setItem(V11_SAFETY_SNAPSHOT_KEY, raw);
    showEventMessage("安全スナップショットを保存した。ここからいつでも戻せる。");
    refreshV11CompletionPanel();
    return true;
  } catch (error) {
    showEventMessage("安全スナップショットの保存に失敗した。" + (error?.message || ""));
    return false;
  }
}

function v11RestoreSafetySnapshot() {
  const raw = localStorage.getItem(V11_SAFETY_SNAPSHOT_KEY);
  if (!raw) {
    showEventMessage("安全スナップショットはまだない。");
    return;
  }

  const ok = confirm(
    "安全スナップショットの状態へ戻します。現在のセーブは上書きされます。よろしいですか？"
  );
  if (!ok) return;

  try {
    JSON.parse(raw);
    localStorage.setItem(SAVE_KEY, raw);
    location.reload();
  } catch {
    showEventMessage("安全スナップショットが壊れているため復元できなかった。");
  }
}

function v11ApplyReleasePreview() {
  const panel = document.querySelector("#gameTestPanel");
  if (panel) {
    panel.style.display = metaProgress.v11.releasePreview ? "none" : "";
  }

  if (v11ReleaseButtonEl) {
    v11ReleaseButtonEl.textContent = metaProgress.v11.releasePreview
      ? "開発表示へ戻す"
      : "本番プレビューに切替";
  }
}

function v11ToggleReleasePreview() {
  metaProgress.v11.releasePreview = !metaProgress.v11.releasePreview;
  saveGame();
  v11ApplyReleasePreview();
  showEventMessage(
    metaProgress.v11.releasePreview
      ? "本番プレビュー：テストパネルを隠した。ゲーム機能はそのまま。"
      : "開発表示へ戻した。"
  );
}

function v11TogglePlaytestCheck(id) {
  const set = new Set(metaProgress.v11.completedPlaytestChecks || []);
  if (set.has(id)) set.delete(id);
  else set.add(id);
  metaProgress.v11.completedPlaytestChecks = [...set];
  saveGame();
  refreshV11CompletionPanel();
}

function v11CopyText(textValue) {
  if (navigator.clipboard?.writeText) {
    navigator.clipboard.writeText(textValue).then(
      () => showEventMessage("レポートをコピーした。"),
      () => v11FallbackCopy(textValue)
    );
    return;
  }
  v11FallbackCopy(textValue);
}

function v11FallbackCopy(textValue) {
  const area = document.createElement("textarea");
  area.value = textValue;
  area.style.position = "fixed";
  area.style.opacity = "0";
  document.body.appendChild(area);
  area.select();
  try {
    document.execCommand("copy");
    showEventMessage("レポートをコピーした。");
  } catch {
    showEventMessage("自動コピーできなかった。レポート欄から手動でコピーしてね。");
  }
  area.remove();
}

function v11RecordClientError(message) {
  if (!metaProgress?.v11) return;
  metaProgress.v11.errorLog.push({
    time: Date.now(),
    message: String(message || "不明なエラー").slice(0, 500)
  });
  metaProgress.v11.errorLog = metaProgress.v11.errorLog.slice(-V11_ERROR_LOG_LIMIT);
}

function createV11CompletionPanel() {
  if (v11CompletionPanelEl) return;

  v11CompletionPanelEl = document.createElement("details");
  v11CompletionPanelEl.id = "v11CompletionPanel";
  v11CompletionPanelEl.style.margin = "14px auto";
  v11CompletionPanelEl.style.padding = "12px";
  v11CompletionPanelEl.style.maxWidth = "560px";
  v11CompletionPanelEl.style.border = "2px solid #999";
  v11CompletionPanelEl.style.borderRadius = "12px";
  v11CompletionPanelEl.style.background = "#fff";
  v11CompletionPanelEl.style.color = "#222";

  const summary = document.createElement("summary");
  summary.textContent = "🛠️ 完成本番準備・プレイテスト";
  summary.style.cursor = "pointer";
  summary.style.fontWeight = "bold";
  v11CompletionPanelEl.appendChild(summary);

  if (backupPanelEl) backupPanelEl.insertAdjacentElement("afterend", v11CompletionPanelEl);
  else restartButton.insertAdjacentElement("afterend", v11CompletionPanelEl);

  refreshV11CompletionPanel();
}

function refreshV11CompletionPanel() {
  if (!v11CompletionPanelEl) return;

  const wasOpen = v11CompletionPanelEl.open;
  const audit = v11RunIntegrityAudit({ saveResult: false });
  const snapshotExists = Boolean(localStorage.getItem(V11_SAFETY_SNAPSHOT_KEY));
  const done = new Set(metaProgress.v11.completedPlaytestChecks || []);

  v11CompletionPanelEl.innerHTML = "";

  const summary = document.createElement("summary");
  summary.textContent = "🛠️ 完成本番準備・プレイテスト";
  summary.style.cursor = "pointer";
  summary.style.fontWeight = "bold";
  v11CompletionPanelEl.appendChild(summary);

  const status = document.createElement("div");
  status.style.marginTop = "10px";
  status.style.padding = "10px";
  status.style.border = "1px solid #ddd";
  status.style.borderRadius = "10px";
  status.style.whiteSpace = "pre-wrap";
  status.textContent =
    "自動整合性：" + (audit.errors.length ? "❌ " + audit.errors.length + "件" : "✅ 重大エラーなし") + "\n" +
    "本番画像：未差し替え候補 " + audit.placeholderAssets.length + "枠\n" +
    "手動テスト：" + done.size + " / " + V11_PLAYTEST_CHECKS.length + "項目\n" +
    "安全スナップショット：" + (snapshotExists ? "保存済み" : "未作成");
  v11CompletionPanelEl.appendChild(status);

  const buttonRow = document.createElement("div");
  buttonRow.style.marginTop = "10px";

  const auditButton = document.createElement("button");
  auditButton.textContent = "自動整合性チェック";
  auditButton.style.margin = "3px";
  auditButton.addEventListener("click", () => {
    const result = v11RunIntegrityAudit({ saveResult: true });
    refreshV11CompletionPanel();
    showEventMessage(
      result.errors.length
        ? "整合性チェック：エラー " + result.errors.length + "件。"
        : "整合性チェックOK。重大な構造エラーは見つからなかった。"
    );
  });
  buttonRow.appendChild(auditButton);

  const snapshotButton = document.createElement("button");
  snapshotButton.textContent = "安全スナップショット保存";
  snapshotButton.style.margin = "3px";
  snapshotButton.addEventListener("click", v11CreateSafetySnapshot);
  buttonRow.appendChild(snapshotButton);

  const restoreButton = document.createElement("button");
  restoreButton.textContent = "スナップショット復元";
  restoreButton.style.margin = "3px";
  restoreButton.disabled = !snapshotExists;
  restoreButton.addEventListener("click", v11RestoreSafetySnapshot);
  buttonRow.appendChild(restoreButton);

  v11ReleaseButtonEl = document.createElement("button");
  v11ReleaseButtonEl.style.margin = "3px";
  v11ReleaseButtonEl.addEventListener("click", v11ToggleReleasePreview);
  buttonRow.appendChild(v11ReleaseButtonEl);

  v11CompletionPanelEl.appendChild(buttonRow);

  const balance = document.createElement("details");
  balance.style.marginTop = "10px";
  const balanceSummary = document.createElement("summary");
  balanceSummary.textContent = "⏱️ 現在の本番バランス設定";
  balance.appendChild(balanceSummary);
  const balanceText = document.createElement("div");
  balanceText.style.whiteSpace = "pre-wrap";
  balanceText.style.marginTop = "6px";
  balanceText.textContent =
    "ベビーでーもん " + v11Hours(aliveStages[0].durationSeconds) + "時間\n" +
    "でーちゃん " + v11Hours(aliveStages[1].durationSeconds) + "時間\n" +
    "少年 " + v11Hours(aliveStages[2].durationSeconds) + "時間\n" +
    "大人 " + v11Hours(aliveStages[3].durationSeconds) + "時間\n" +
    "老年 " + v11Hours(aliveStages[4].durationSeconds) + "時間\n" +
    "合計 " + v11Hours(TOTAL_LIFE_SECONDS) + "時間（2日半）\n\n" +
    "ステータス自然減少：" + Math.round(DECAY_INTERVAL_MS / 60000) + "分ごと\n" +
    "0状態から死亡：" + v11Hours(ZERO_DEATH_MS / 1000) + "時間\n" +
    "ランダムイベント：" + Math.round(RANDOM_EVENT_MIN_MS / 60000) + "〜" + Math.round(RANDOM_EVENT_MAX_MS / 60000) + "分\n" +
    "ゾンビ第二人生：" + v11Hours(ZOMBIE_PHASE_DURATION_SECONDS) + "時間";
  balance.appendChild(balanceText);
  v11CompletionPanelEl.appendChild(balance);

  const assets = document.createElement("details");
  assets.style.marginTop = "10px";
  const assetsSummary = document.createElement("summary");
  assetsSummary.textContent = "🖼️ 本番画像の差し替え待ち " + audit.placeholderAssets.length + "枠";
  assets.appendChild(assetsSummary);
  const assetsText = document.createElement("div");
  assetsText.style.whiteSpace = "pre-wrap";
  assetsText.style.marginTop = "6px";
  assetsText.textContent = audit.placeholderAssets.length
    ? audit.placeholderAssets.map(item => "・" + item.category + "：" + item.label).join("\n")
    : "仮画像は検出されなかった。";
  assets.appendChild(assetsText);
  v11CompletionPanelEl.appendChild(assets);

  const checklist = document.createElement("details");
  checklist.style.marginTop = "10px";
  const checklistSummary = document.createElement("summary");
  checklistSummary.textContent = "✅ 本番前プレイテスト " + done.size + "/" + V11_PLAYTEST_CHECKS.length;
  checklist.appendChild(checklistSummary);

  V11_PLAYTEST_CHECKS.forEach(([id, label]) => {
    const row = document.createElement("label");
    row.style.display = "block";
    row.style.margin = "6px 0";
    row.style.cursor = "pointer";
    const check = document.createElement("input");
    check.type = "checkbox";
    check.checked = done.has(id);
    check.style.marginRight = "7px";
    check.addEventListener("change", () => v11TogglePlaytestCheck(id));
    row.appendChild(check);
    row.appendChild(document.createTextNode(label));
    checklist.appendChild(row);
  });
  v11CompletionPanelEl.appendChild(checklist);

  const reportDetails = document.createElement("details");
  reportDetails.style.marginTop = "10px";
  const reportSummary = document.createElement("summary");
  reportSummary.textContent = "📄 本番準備・バグ報告レポート";
  reportDetails.appendChild(reportSummary);

  v11ReportTextareaEl = document.createElement("textarea");
  v11ReportTextareaEl.rows = 12;
  v11ReportTextareaEl.style.width = "100%";
  v11ReportTextareaEl.style.boxSizing = "border-box";
  v11ReportTextareaEl.style.marginTop = "8px";
  v11ReportTextareaEl.value = v11BuildReportText();
  reportDetails.appendChild(v11ReportTextareaEl);

  const refreshReport = document.createElement("button");
  refreshReport.textContent = "レポート更新";
  refreshReport.style.margin = "4px";
  refreshReport.addEventListener("click", () => {
    v11ReportTextareaEl.value = v11BuildReportText();
  });
  reportDetails.appendChild(refreshReport);

  const copyReport = document.createElement("button");
  copyReport.textContent = "レポートをコピー";
  copyReport.style.margin = "4px";
  copyReport.addEventListener("click", () => {
    v11ReportTextareaEl.value = v11BuildReportText();
    v11CopyText(v11ReportTextareaEl.value);
  });
  reportDetails.appendChild(copyReport);

  v11CompletionPanelEl.appendChild(reportDetails);

  const lastErrors = document.createElement("details");
  lastErrors.style.marginTop = "10px";
  const errorSummary = document.createElement("summary");
  errorSummary.textContent = "🐞 JavaScriptエラー記録 " + metaProgress.v11.errorLog.length + "件";
  lastErrors.appendChild(errorSummary);
  const errorText = document.createElement("div");
  errorText.style.whiteSpace = "pre-wrap";
  errorText.style.marginTop = "6px";
  errorText.textContent = metaProgress.v11.errorLog.length
    ? metaProgress.v11.errorLog
        .slice()
        .reverse()
        .map(entry => new Date(entry.time).toLocaleString() + "\n" + entry.message)
        .join("\n\n")
    : "今のところ記録されたJavaScriptエラーはない。";
  lastErrors.appendChild(errorText);
  v11CompletionPanelEl.appendChild(lastErrors);

  v11CompletionPanelEl.open = wasOpen;
  v11ApplyReleasePreview();
  v13ApplyProductionMode();
}

function v11RefreshAll() {
  refreshV11CompletionPanel();
  v11ApplyReleasePreview();
}

window.addEventListener("error", event => {
  v11RecordClientError(event?.message || "window error");
});

window.addEventListener("unhandledrejection", event => {
  const reason = event?.reason;
  v11RecordClientError(reason?.message || String(reason || "unhandled rejection"));
});

/* =========================
   v1.8 本番画像アセット管理
========================= */

function v12AssetSlots() {
  const slots = [];

  adultTypeIds.filter(id => id !== "normal").forEach(id => {
    slots.push({ id: "adult:" + id, category: "大人", label: adultLabel(id), group: "adult", routeId: id });
  });

  adultTypeIds.filter(id => id !== "normal").forEach(id => {
    slots.push({ id: "elder:" + id, category: "老年", label: elderLabel(id), group: "elder", routeId: id });
  });

  adultTypeIds.filter(id => id !== "normal").forEach(id => {
    slots.push({ id: "corpse:" + id, category: "老衰後", label: elderLabel(id) + " → 大往生", group: "corpse", routeId: id });
  });

  teenTypeIds.forEach(id => {
    slots.push({ id: "teenDeath:" + id, category: "途中死亡・少年", label: teenLabel(id) + "少年死亡", group: "teenDeath", routeId: id });
  });

  adultTypeIds.filter(id => id !== "normal").forEach(id => {
    slots.push({ id: "adultDeath:" + id, category: "途中死亡・大人", label: adultLabel(id) + "大人死亡", group: "adultDeath", routeId: id });
  });

  adultTypeIds.filter(id => id !== "normal").forEach(id => {
    slots.push({ id: "elderDeath:" + id, category: "途中死亡・老年", label: adultLabel(id) + "老年死亡", group: "elderDeath", routeId: id });
  });

  zombieTypeIds.forEach(id => {
    slots.push({ id: "zombie:" + id, category: "ゾンビ結末", label: zombieLabel(id), group: "zombie", routeId: id });
  });

  return slots;
}

function v12DefaultAssetUrl(slot) {
  if (!slot) return "";
  if (slot.group === "adult") return defaultAdultImage;
  if (slot.group === "elder") return defaultElderImage;
  if (slot.group === "corpse") return naturalDeathStage.image;
  if (slot.group === "teenDeath") return deathStages.teen.image;
  if (slot.group === "adultDeath") return deathStages.adult.image;
  if (slot.group === "elderDeath") return deathStages.elder.image;
  return "";
}

function v12CurrentAssetUrl(slot) {
  if (!slot) return "";
  if (slot.group === "adult") return adultTypeImages[slot.routeId] || "";
  if (slot.group === "elder") return elderTypeImages[slot.routeId] || "";
  if (slot.group === "corpse") return corpseTypeImages[slot.routeId] || "";
  if (slot.group === "teenDeath") return teenDeathTypeImages[slot.routeId] || "";
  if (slot.group === "adultDeath") return adultDeathTypeImages[slot.routeId] || "";
  if (slot.group === "elderDeath") return elderDeathTypeImages[slot.routeId] || "";
  if (slot.group === "zombie") return zombieTypeImages[slot.routeId] || "";
  return "";
}

function v12SetMappedAsset(slot, url) {
  if (!slot) return;
  const value = url || v12DefaultAssetUrl(slot);

  if (slot.group === "adult") adultTypeImages[slot.routeId] = value;
  else if (slot.group === "elder") elderTypeImages[slot.routeId] = value;
  else if (slot.group === "corpse") corpseTypeImages[slot.routeId] = value;
  else if (slot.group === "teenDeath") teenDeathTypeImages[slot.routeId] = value;
  else if (slot.group === "adultDeath") adultDeathTypeImages[slot.routeId] = value;
  else if (slot.group === "elderDeath") elderDeathTypeImages[slot.routeId] = value;
  else if (slot.group === "zombie") zombieTypeImages[slot.routeId] = url || null;
}

function v12ApplyAllAssetOverrides() {
  if (!metaProgress?.v12) return;
  const overrides = metaProgress.v12.assetOverrides || {};
  v12AssetSlots().forEach(slot => {
    const url = typeof overrides[slot.id] === "string" ? overrides[slot.id].trim() : "";
    v12SetMappedAsset(slot, url);
  });
}

function v12IsAssetConfigured(slot) {
  return Boolean(metaProgress.v12.assetOverrides?.[slot.id]);
}

function v12IsAssetApproved(slot) {
  return metaProgress.v12.approvedAssets.includes(slot.id);
}

function v12AssetProgress() {
  const slots = v12AssetSlots();
  const configured = slots.filter(v12IsAssetConfigured).length;
  const approved = slots.filter(v12IsAssetApproved).length;
  return {
    total: slots.length,
    configured,
    approved,
    configuredPercent: slots.length ? Math.round((configured / slots.length) * 100) : 100,
    approvedPercent: slots.length ? Math.round((approved / slots.length) * 100) : 100
  };
}

function v12MissingAssetListText() {
  const missing = v12AssetSlots().filter(slot => !v12IsAssetConfigured(slot));
  if (!missing.length) return "本番画像はすべて設定済み。";

  const groups = {};
  missing.forEach(slot => {
    (groups[slot.category] ||= []).push(slot.label + "  [" + slot.id + "]");
  });

  return Object.entries(groups)
    .map(([category, rows]) => "【" + category + "】\n" + rows.map(x => "・" + x).join("\n"))
    .join("\n\n");
}

function v12ConfiguredAssetExportText() {
  return JSON.stringify(
    {
      version: GAME_VERSION,
      exportedAt: new Date().toISOString(),
      assetOverrides: metaProgress.v12.assetOverrides,
      approvedAssets: metaProgress.v12.approvedAssets
    },
    null,
    2
  );
}

function v12ValidateAndSetAsset(slot, url, onDone) {
  const value = String(url || "").trim();
  if (!value) {
    showEventMessage("画像URLが空欄。解除する場合は『解除』を使ってね。");
    return;
  }

  if (!/^https?:\/\//i.test(value) && !/^data:image\//i.test(value)) {
    showEventMessage("画像URLは http / https の直リンクを入れてね。");
    return;
  }

  const img = new Image();
  img.onload = () => {
    metaProgress.v12.assetOverrides[slot.id] = value;
    metaProgress.v12.lastAssetEditAt = Date.now();
    v12SetMappedAsset(slot, value);
    saveGame();
    updateView();
    refreshV12AssetPanel();
    refreshV11CompletionPanel();
    showEventMessage(slot.label + " の画像を反映した。");
    if (typeof onDone === "function") onDone(true);
  };
  img.onerror = () => {
    showEventMessage("画像を読み込めなかった。ImgBBなら『画像そのもののURL』を使ってね。");
    if (typeof onDone === "function") onDone(false);
  };
  img.src = value;
}

function v12ClearAsset(slot) {
  delete metaProgress.v12.assetOverrides[slot.id];
  metaProgress.v12.approvedAssets = metaProgress.v12.approvedAssets.filter(id => id !== slot.id);
  metaProgress.v12.lastAssetEditAt = Date.now();
  v12SetMappedAsset(slot, "");
  saveGame();
  updateView();
  refreshV12AssetPanel();
  refreshV11CompletionPanel();
  showEventMessage(slot.label + " を仮画像へ戻した。");
}

function v12ToggleApproved(slot, checked) {
  const set = new Set(metaProgress.v12.approvedAssets);
  if (checked && v12IsAssetConfigured(slot)) set.add(slot.id);
  else set.delete(slot.id);
  metaProgress.v12.approvedAssets = [...set];
  metaProgress.v12.lastAssetEditAt = Date.now();
  saveGame();
  refreshV12AssetPanel();
}

function v12PreviewAsset(slot) {
  if (!v12AssetPreviewEl) return;
  const url = v12CurrentAssetUrl(slot) || v12DefaultAssetUrl(slot);
  if (!url) {
    v12AssetPreviewEl.removeAttribute("src");
    v12AssetPreviewEl.alt = "画像未設定";
    showEventMessage(slot.label + " はまだ本番画像未設定。" );
    return;
  }
  v12AssetPreviewEl.src = url;
  v12AssetPreviewEl.alt = slot.label;
}

function v12ImportAssetJson(raw) {
  let data;
  try {
    data = JSON.parse(raw);
  } catch {
    showEventMessage("画像設定JSONを読み込めなかった。");
    return false;
  }

  const allowed = new Set(v12AssetSlots().map(slot => slot.id));
  const incoming = data?.assetOverrides;
  if (!incoming || typeof incoming !== "object") {
    showEventMessage("assetOverrides が見つからない。");
    return false;
  }

  const clean = {};
  Object.entries(incoming).forEach(([id, url]) => {
    if (allowed.has(id) && typeof url === "string" && url.trim()) {
      clean[id] = url.trim();
    }
  });

  metaProgress.v12.assetOverrides = clean;
  metaProgress.v12.approvedAssets = Array.isArray(data?.approvedAssets)
    ? [...new Set(data.approvedAssets.filter(id => allowed.has(id) && clean[id]))]
    : [];
  metaProgress.v12.lastAssetEditAt = Date.now();
  v12ApplyAllAssetOverrides();
  saveGame();
  updateView();
  refreshV12AssetPanel();
  refreshV11CompletionPanel();
  showEventMessage("画像設定を読み込んだ。" );
  return true;
}

function createV12AssetPanel() {
  if (v12AssetPanelEl) return;

  v12AssetPanelEl = document.createElement("details");
  v12AssetPanelEl.id = "v12AssetPanel";
  v12AssetPanelEl.style.margin = "14px auto";
  v12AssetPanelEl.style.padding = "12px";
  v12AssetPanelEl.style.maxWidth = "560px";
  v12AssetPanelEl.style.border = "2px solid #999";
  v12AssetPanelEl.style.borderRadius = "12px";
  v12AssetPanelEl.style.background = "#fff";
  v12AssetPanelEl.style.color = "#222";

  if (v11CompletionPanelEl) v11CompletionPanelEl.insertAdjacentElement("afterend", v12AssetPanelEl);
  else restartButton.insertAdjacentElement("afterend", v12AssetPanelEl);

  refreshV12AssetPanel();
}

function refreshV12AssetPanel() {
  if (!v12AssetPanelEl) return;
  const wasOpen = v12AssetPanelEl.open;
  const progress = v12AssetProgress();
  const slots = v12AssetSlots();

  v12AssetPanelEl.innerHTML = "";

  const summary = document.createElement("summary");
  summary.textContent = "🖼️ 本番画像管理 " + progress.configured + "/" + progress.total + " 設定済み";
  summary.style.cursor = "pointer";
  summary.style.fontWeight = "bold";
  v12AssetPanelEl.appendChild(summary);

  const status = document.createElement("div");
  status.style.marginTop = "10px";
  status.style.padding = "10px";
  status.style.border = "1px solid #ddd";
  status.style.borderRadius = "10px";
  status.style.whiteSpace = "pre-wrap";
  status.textContent =
    "URL設定：" + progress.configured + "/" + progress.total + "（" + progress.configuredPercent + "%）\n" +
    "本番確定：" + progress.approved + "/" + progress.total + "（" + progress.approvedPercent + "%）\n" +
    "※ 画像IDは内部IDなので、将来ルート名を変更しても画像設定は崩れない。";
  v12AssetPanelEl.appendChild(status);

  const controls = document.createElement("div");
  controls.style.margin = "10px 0";

  const copyMissing = document.createElement("button");
  copyMissing.textContent = "未完成画像リストをコピー";
  copyMissing.style.margin = "3px";
  copyMissing.addEventListener("click", () => v11CopyText(v12MissingAssetListText()));
  controls.appendChild(copyMissing);

  const copyJson = document.createElement("button");
  copyJson.textContent = "画像設定JSONをコピー";
  copyJson.style.margin = "3px";
  copyJson.addEventListener("click", () => v11CopyText(v12ConfiguredAssetExportText()));
  controls.appendChild(copyJson);

  const nextMissing = document.createElement("button");
  nextMissing.textContent = "次に作る画像";
  nextMissing.style.margin = "3px";
  nextMissing.addEventListener("click", () => {
    const next = slots.find(slot => !v12IsAssetConfigured(slot));
    showEventMessage(next ? "次の画像候補：" + next.category + " / " + next.label : "本番画像は全部設定済み！");
  });
  controls.appendChild(nextMissing);

  v12AssetPanelEl.appendChild(controls);

  v12AssetPreviewEl = document.createElement("img");
  v12AssetPreviewEl.style.display = "block";
  v12AssetPreviewEl.style.maxWidth = "100%";
  v12AssetPreviewEl.style.maxHeight = "320px";
  v12AssetPreviewEl.style.objectFit = "contain";
  v12AssetPreviewEl.style.margin = "10px auto";
  v12AssetPreviewEl.style.borderRadius = "10px";
  v12AssetPanelEl.appendChild(v12AssetPreviewEl);

  const importDetails = document.createElement("details");
  importDetails.style.margin = "10px 0";
  const importSummary = document.createElement("summary");
  importSummary.textContent = "📥 画像設定JSONを読み込む";
  importDetails.appendChild(importSummary);
  const importArea = document.createElement("textarea");
  importArea.rows = 6;
  importArea.placeholder = "ここへ画像設定JSONを貼り付け";
  importArea.style.width = "100%";
  importArea.style.boxSizing = "border-box";
  importArea.style.marginTop = "6px";
  importDetails.appendChild(importArea);
  const importButton = document.createElement("button");
  importButton.textContent = "JSONを反映";
  importButton.style.marginTop = "6px";
  importButton.addEventListener("click", () => v12ImportAssetJson(importArea.value));
  importDetails.appendChild(importButton);
  v12AssetPanelEl.appendChild(importDetails);

  const categories = [...new Set(slots.map(slot => slot.category))];
  categories.forEach(category => {
    const details = document.createElement("details");
    details.style.marginTop = "8px";
    const groupSlots = slots.filter(slot => slot.category === category);
    const configured = groupSlots.filter(v12IsAssetConfigured).length;
    const groupSummary = document.createElement("summary");
    groupSummary.textContent = category + "  " + configured + "/" + groupSlots.length;
    groupSummary.style.fontWeight = "bold";
    details.appendChild(groupSummary);

    groupSlots.forEach(slot => {
      const row = document.createElement("div");
      row.style.padding = "9px 0";
      row.style.borderBottom = "1px solid #eee";

      const title = document.createElement("div");
      title.style.fontWeight = "bold";
      title.textContent = (v12IsAssetConfigured(slot) ? "✅ " : "⬜ ") + slot.label;
      row.appendChild(title);

      const idText = document.createElement("div");
      idText.style.fontSize = "12px";
      idText.style.opacity = "0.65";
      idText.textContent = slot.id;
      row.appendChild(idText);

      const input = document.createElement("input");
      input.type = "url";
      input.placeholder = "https://... 画像の直リンク";
      input.value = metaProgress.v12.assetOverrides[slot.id] || "";
      input.style.width = "100%";
      input.style.boxSizing = "border-box";
      input.style.margin = "6px 0";
      row.appendChild(input);

      const apply = document.createElement("button");
      apply.textContent = "反映";
      apply.style.marginRight = "4px";
      apply.addEventListener("click", () => v12ValidateAndSetAsset(slot, input.value));
      row.appendChild(apply);

      const preview = document.createElement("button");
      preview.textContent = "プレビュー";
      preview.style.marginRight = "4px";
      preview.addEventListener("click", () => v12PreviewAsset(slot));
      row.appendChild(preview);

      const clear = document.createElement("button");
      clear.textContent = "解除";
      clear.style.marginRight = "8px";
      clear.disabled = !v12IsAssetConfigured(slot);
      clear.addEventListener("click", () => v12ClearAsset(slot));
      row.appendChild(clear);

      const approvedLabel = document.createElement("label");
      approvedLabel.style.marginLeft = "4px";
      approvedLabel.style.cursor = v12IsAssetConfigured(slot) ? "pointer" : "default";
      const approved = document.createElement("input");
      approved.type = "checkbox";
      approved.checked = v12IsAssetApproved(slot);
      approved.disabled = !v12IsAssetConfigured(slot);
      approved.style.marginRight = "4px";
      approved.addEventListener("change", () => v12ToggleApproved(slot, approved.checked));
      approvedLabel.appendChild(approved);
      approvedLabel.appendChild(document.createTextNode("本番確定"));
      row.appendChild(approvedLabel);

      details.appendChild(row);
    });

    v12AssetPanelEl.appendChild(details);
  });

  const danger = document.createElement("details");
  danger.style.marginTop = "12px";
  const dangerSummary = document.createElement("summary");
  dangerSummary.textContent = "⚠️ 画像設定を全部解除";
  danger.appendChild(dangerSummary);
  const resetButton = document.createElement("button");
  resetButton.textContent = "全画像設定を仮画像へ戻す";
  resetButton.style.marginTop = "8px";
  resetButton.addEventListener("click", () => {
    if (!confirm("本番画像のURL設定と本番確定チェックを全部解除します。よろしいですか？")) return;
    metaProgress.v12.assetOverrides = {};
    metaProgress.v12.approvedAssets = [];
    metaProgress.v12.lastAssetEditAt = Date.now();
    v12ApplyAllAssetOverrides();
    saveGame();
    updateView();
    refreshV12AssetPanel();
    refreshV11CompletionPanel();
    showEventMessage("画像設定をすべて仮画像へ戻した。" );
  });
  danger.appendChild(resetButton);
  v12AssetPanelEl.appendChild(danger);

  v12AssetPanelEl.open = wasOpen;
}

function v12EnhanceTestPanel() {
  const panel = document.querySelector("#gameTestPanel");
  if (!panel || panel.querySelector("#v12AssetTestTools")) return;

  const wrap = document.createElement("div");
  wrap.id = "v12AssetTestTools";
  wrap.style.marginTop = "12px";

  const title = document.createElement("div");
  title.textContent = "v1.8 本番画像管理テスト";
  title.style.fontWeight = "bold";
  title.style.marginBottom = "6px";
  wrap.appendChild(title);

  const openButton = document.createElement("button");
  openButton.textContent = "本番画像管理を開く";
  openButton.style.margin = "3px";
  openButton.addEventListener("click", () => {
    if (!v12AssetPanelEl) return;
    v12AssetPanelEl.open = true;
    v12AssetPanelEl.scrollIntoView({ behavior: "smooth", block: "start" });
  });
  wrap.appendChild(openButton);

  const copyButton = document.createElement("button");
  copyButton.textContent = "未完成画像リストをコピー";
  copyButton.style.margin = "3px";
  copyButton.addEventListener("click", () => v11CopyText(v12MissingAssetListText()));
  wrap.appendChild(copyButton);

  panel.appendChild(wrap);
}

/* =========================
   テスト用年代ジャンプ
========================= */

function jumpToStage(stageKey) {
  demonLaboBaseTeenPreview = false;
  let startSeconds = 0;

  for (const stage of aliveStages) {
    if (stage.key === stageKey) break;
    startSeconds += getRuntimeStageDurationSeconds(stage);
  }

  birthTime = Date.now() - (startSeconds + 5) * 1000;
  lastDecay = Date.now();
  zeroStartTime = null;

  isDead = false;
  deathKind = null;
  deathStageKey = null;
  deathRouteType = null;
  specialState = null;
  zombieState = createEmptyZombieState();

  if (["baby", "child"].includes(stageKey)) {
    teenType = null;
    adultType = null;
    elderType = null;
  } else if (stageKey === "teen") {
    adultType = null;
    elderType = null;
  } else if (stageKey === "adult") {
    elderType = null;
  }

  saveGame();
  updateStatus();
  updateView();
}

function previewBaseTeenStage() {
  let startSeconds = 0;

  for (const stage of aliveStages) {
    if (stage.key === "teen") break;
    startSeconds += getRuntimeStageDurationSeconds(stage);
  }

  birthTime = Date.now() - (startSeconds + 5) * 1000;
  lastDecay = Date.now();
  zeroStartTime = null;

  isDead = false;
  deathKind = null;
  deathStageKey = null;
  deathRouteType = null;
  specialState = null;
  zombieState = createEmptyZombieState();

  teenType = null;
  adultType = null;
  elderType = null;
  demonLaboBaseTeenPreview = true;

  saveGame();
  updateStatus();
  updateView();

  // テスト用「でーもん少年」は分岐画像ではなく、
  // 登録済みの 03_alive_teen_base.mp4 (alive:teen) を必ず表示する。
  const baseTeenStage = aliveStages.find(stage => stage.key === "teen");
  if (baseTeenStage) {
    stageNameEl.textContent = "でーもん少年";
    currentStageText.textContent = "現在：でーもん少年";
    specialActionButton.style.display = "none";
    setDemonLaboCharacterVisual(
      baseTeenStage.image,
      "でーもん少年",
      "alive:teen"
    );
  }
}

function previewBaseAdultStage() {
  demonLaboBaseTeenPreview = false;

  let startSeconds = 0;
  for (const stage of aliveStages) {
    if (stage.key === "adult") break;
    startSeconds += getRuntimeStageDurationSeconds(stage);
  }

  birthTime = Date.now() - (startSeconds + 5) * 1000;
  lastDecay = Date.now();
  zeroStartTime = null;

  isDead = false;
  deathKind = null;
  deathStageKey = null;
  deathRouteType = null;
  specialState = null;
  zombieState = createEmptyZombieState();

  // 「年代ジャンプ → でーもん」は分岐判定をさせず、
  // 必ず普通のでーもんを直接表示する。
  adultType = "normal";
  elderType = null;

  saveGame();
  updateStatus();
  updateView();

  // 最後に表示も直接固定して、過去のニートルート等が残っていても
  // 08_adult_normal.mp4 を必ず表示する。
  const baseAdultStage = aliveStages.find(stage => stage.key === "adult");
  if (baseAdultStage) {
    stageNameEl.textContent = "でーもん";
    currentStageText.textContent = "現在：でーもん";
    setDemonLaboCharacterVisual(
      adultTypeImages.normal || baseAdultStage.image,
      "でーもん",
      "adult:normal"
    );

    const action = adultSpecialActions.normal;
    if (action) {
      specialActionButton.style.display = "";
      specialActionButton.textContent =
        action.label + "（" + (adultSpecialHistory.normal || 0) + "回）";
    }
  }
}

function previewBaseElderStage() {
  demonLaboBaseTeenPreview = false;

  let startSeconds = 0;
  for (const stage of aliveStages) {
    if (stage.key === "elder") break;
    startSeconds += getRuntimeStageDurationSeconds(stage);
  }

  birthTime = Date.now() - (startSeconds + 5) * 1000;
  lastDecay = Date.now();
  zeroStartTime = null;

  isDead = false;
  deathKind = null;
  deathStageKey = null;
  deathRouteType = null;
  specialState = null;
  zombieState = createEmptyZombieState();

  // 「年代ジャンプ → ジジィでーもん」は過去の大人ルートを引き継がず、
  // 必ず普通の老年ルートを直接表示する。
  adultType = "normal";
  elderType = "normal";

  saveGame();
  updateStatus();
  updateView();

  // updateView 内の自動ルート判定より後に、表示も normal に固定する。
  const baseElderStage = aliveStages.find(stage => stage.key === "elder");
  if (baseElderStage) {
    stageNameEl.textContent = "ジジィでーもん";
    currentStageText.textContent = "現在：ジジィでーもん";

    setDemonLaboCharacterVisual(
      elderTypeImages.normal || baseElderStage.image,
      "ジジィでーもん",
      "elder:normal"
    );

    const action = elderSpecialActions.normal;
    if (action) {
      specialActionButton.style.display = "";
      specialActionButton.textContent =
        action.label + "（" + (elderSpecialHistory.normal || 0) + "回）";
    }
  }
}

function forceTeenType(typeId) {
  jumpToStage("teen");
  demonLaboBaseTeenPreview = false;
  teenType = typeId;
  adultType = null;
  elderType = null;
  unlockTeenType(typeId);
  saveGame();
  updateStatus();
  updateView();
}

function forceAdultType(typeId) {
  jumpToStage("adult");
  adultType = typeId;
  elderType = null;
  unlockRoute(typeId);
  saveGame();
  updateStatus();
  updateView();
}

function forceElderType(typeId) {
  jumpToStage("elder");
  unlockRoute(typeId);
  adultType = typeId;
  elderType = typeId;
  saveGame();
  updateStatus();
  updateView();
}

function forceNaturalDeath(typeId) {
  zombieState = createEmptyZombieState();
  adultType = typeId;
  elderType = typeId;
  isDead = true;
  deathKind = "natural";
  deathStageKey = null;
  deathRouteType = typeId;
  specialEndingId = null;
  specialState = null;
  saveGame();
  updateStatus();
  updateView();
}

function forceMidDeath(stageKey, routeType = null) {
  jumpToStage(stageKey);
  zombieState = createEmptyZombieState();

  if (stageKey === "teen") {
    teenType = normalizeTeenTypeId(routeType) || "honest";
  }

  if (stageKey === "adult") {
    adultType = normalizeAdultTypeId(routeType) || "normal";
  }

  if (stageKey === "elder") {
    adultType = normalizeAdultTypeId(routeType) || "normal";
    elderType = normalizeAdultTypeId(routeType) || "normal";
  }

  isDead = true;
  deathKind = "mid";
  deathStageKey = stageKey;
  deathRouteType =
    stageKey === "teen" ? teenType : adultType;
  specialEndingId = null;
  specialState = null;

  saveGame();
  updateStatus();
  updateView();
}

function forceZombieDeath(stageKey = "adult", routeType = "fallen") {
  jumpToStage(stageKey);

  if (stageKey === "teen") {
    teenType = normalizeTeenTypeId(routeType) || "trouble";
  } else if (stageKey === "adult") {
    adultType = normalizeAdultTypeId(routeType) || "fallen";
  } else if (stageKey === "elder") {
    adultType = normalizeAdultTypeId(routeType) || "fallen";
    elderType = adultType;
  }

  routeFlags.specialDeathSeed = true;
  triggerZombieDeath(Date.now());
  updateStatus();
  updateView();
}

function forceAwakenedRoute() {
  jumpToStage("teen");
  teenType = "honest";
  routeFlags.hiddenGrowthSeed = true;
  routeFlags.hiddenGrowthAwakened = true;
  routeFlags.awakenedRoute = true;
  specialState = "awakened";
  unlockTeenType(teenType);
  unlockSpecial("hidden_growth_awakened");
  unlockSpecial("awakened_route");
  recordGameEvent(
    "awakened_route_entered",
    "テスト用に覚醒ルートへ入った。"
  );
  updateStatus();
  updateView();
}

function forceDrugZombieCondition() {
  jumpToStage("adult");
  teenType = "trouble";
  adultType = "fallen";
  elderType = null;
  routeFlags.usedSuspiciousDrug = true;
  routeFlags.forcedAdultType = "fallen";
  routeFlags.specialDeathSeed = false;
  careHistory.adult.danger = Math.max(2, careHistory.adult.danger || 0);
  unlockTeenType("trouble");
  unlockRoute("fallen");
  triggerMidDeath(Date.now());
  updateStatus();
  updateView();
}

