/* =========================
   v2.0 リリース前自動診断・主要ルート検査
========================= */

let v14ReleasePanelEl = null;
let v14RouteReportEl = null;
let v14SaveReportEl = null;
let v14ReleaseReportEl = null;
let v14SecretTapCount = 0;
let v14SecretTapTimer = null;

function v14FmtTime(value) {
  return Number.isFinite(value) ? new Date(value).toLocaleString() : "未実行";
}

function v14EmptyAdultHistory() {
  return createEmptyStageHistory();
}

function v14RunRouteAudit({ saveResult = true } = {}) {
  const results = [];
  const add = (category, name, expected, actual) => {
    results.push({ category, name, expected, actual, pass: expected === actual });
  };

  // 少年4タイプは純粋関数で検査。
  add("少年", "問題児", "trouble", predictTeenTypeFromHistory({ ...createEmptyStageHistory(), danger: 2 }));
  add("少年", "パリピ", "party", predictTeenTypeFromHistory({ ...createEmptyStageHistory(), play: 3 }));
  add("少年", "素直", "honest", predictTeenTypeFromHistory({ ...createEmptyStageHistory(), feed: 2, sleep: 2, bath: 2 }));
  add("少年", "陰気", "introvert", predictTeenTypeFromHistory(createEmptyStageHistory()));

  const original = {
    careHistory,
    teenSpecialHistory,
    adultSpecialHistory,
    routeFlags,
    zombieState,
    permanentItems: metaProgress.permanentItems
  };

  const resetSandbox = () => {
    careHistory = createEmptyCareHistory();
    teenSpecialHistory = Object.fromEntries(teenTypeIds.map(id => [id, 0]));
    adultSpecialHistory = Object.fromEntries(adultTypeIds.map(id => [id, 0]));
    routeFlags = normalizeRouteFlags(null);
    zombieState = createEmptyZombieState();
    metaProgress.permanentItems = [];
  };

  try {
    // 大人8ルート
    resetSandbox();
    add("大人", "素直→普通", "normal", predictAdultType("honest"));

    resetSandbox();
    teenSpecialHistory.trouble = 3;
    careHistory.teen.sleep = 2;
    careHistory.teen.bath = 2;
    add("大人", "問題児→格闘家", "fighter", predictAdultType("trouble"));

    resetSandbox();
    teenSpecialHistory.trouble = 3;
    careHistory.teen.play = 3;
    add("大人", "問題児→ヤクザ", "yakuza", predictAdultType("trouble"));

    resetSandbox();
    add("大人", "問題児→落ちぶれ", "fallen", predictAdultType("trouble"));

    resetSandbox();
    teenSpecialHistory.party = 3;
    careHistory.teen.bath = 3;
    add("大人", "パリピ→ホスト", "host", predictAdultType("party"));

    resetSandbox();
    teenSpecialHistory.party = 3;
    careHistory.teen.play = 3;
    add("大人", "パリピ→ロックスター", "rockstar", predictAdultType("party"));

    resetSandbox();
    teenSpecialHistory.introvert = 3;
    add("大人", "陰気→オタク", "otaku", predictAdultType("introvert"));

    resetSandbox();
    teenSpecialHistory.introvert = 3;
    careHistory.teen.play = 3;
    add("大人", "陰気→ギャンブラー", "gambler", predictAdultType("introvert"));

    // 特殊優先条件
    resetSandbox();
    routeFlags.usedSuspiciousDrug = true;
    add("特殊", "怪しい薬→落ちぶれ固定", "fallen", predictAdultType("trouble"));

    resetSandbox();
    routeFlags.forcedAdultType = "rockstar";
    add("特殊", "進路アイテム→強制ロックスター", "rockstar", predictAdultType("party"));

    // 老年8ルート維持＋回復/転落
    for (const id of adultTypeIds) {
      resetSandbox();
      if (id !== "normal" && id !== "fallen") adultSpecialHistory[id] = 3;
      add("老年", adultLabel(id) + "→同系統老年", id, predictElderType(id));
    }

    resetSandbox();
    careHistory.adult.feed = 3;
    careHistory.adult.sleep = 3;
    careHistory.adult.bath = 3;
    add("老年", "落ちぶれ→更生して普通", "normal", predictElderType("fallen"));

    resetSandbox();
    careHistory.adult.danger = 3;
    add("老年", "危険放置→落ちぶれ", "fallen", predictElderType("rockstar"));

    // ゾンビ4結末
    resetSandbox();
    add("ゾンビ", "さまようゾンビ", "wanderer", determineZombieFinalType());

    resetSandbox();
    zombieState.actions.remember = 3;
    add("ゾンビ", "自我ゾンビ", "sentient", determineZombieFinalType());

    resetSandbox();
    zombieState.actions.roam = 3;
    zombieState.actions.feed = 2;
    add("ゾンビ", "暴走ゾンビ", "feral", determineZombieFinalType());

    resetSandbox();
    routeFlags.zombieCureBoost = true;
    zombieState.actions.remember = 2;
    add("ゾンビ", "人間に戻る", "revived", determineZombieFinalType());
  } finally {
    careHistory = original.careHistory;
    teenSpecialHistory = original.teenSpecialHistory;
    adultSpecialHistory = original.adultSpecialHistory;
    routeFlags = original.routeFlags;
    zombieState = original.zombieState;
    metaProgress.permanentItems = original.permanentItems;
  }

  const expectedCoverage = {
    teen: new Set(teenTypeIds),
    adult: new Set(adultTypeIds),
    elder: new Set(adultTypeIds),
    zombie: new Set(zombieTypeIds)
  };
  const actualCoverage = {
    teen: new Set(results.filter(x => x.category === "少年" && x.pass).map(x => x.actual)),
    adult: new Set(results.filter(x => x.category === "大人" && x.pass).map(x => x.actual)),
    elder: new Set(results.filter(x => x.category === "老年" && x.pass).map(x => x.actual)),
    zombie: new Set(results.filter(x => x.category === "ゾンビ" && x.pass).map(x => x.actual))
  };

  const missingCoverage = [];
  Object.entries(expectedCoverage).forEach(([group, expected]) => {
    expected.forEach(id => {
      if (!actualCoverage[group].has(id)) missingCoverage.push(group + ":" + id);
    });
  });

  const failed = results.filter(x => !x.pass);
  const pass = failed.length === 0 && missingCoverage.length === 0;

  if (saveResult) {
    metaProgress.v14.lastRouteAuditAt = Date.now();
    metaProgress.v14.lastRouteAuditPassed = pass;
    metaProgress.v14.lastRouteAuditPassedCount = results.length - failed.length;
    metaProgress.v14.lastRouteAuditTotalCount = results.length;
    if (pass) {
      const set = new Set(metaProgress.v13.completedFinalChecks || []);
      set.add("routes");
      metaProgress.v13.completedFinalChecks = [...set];
    }
    saveGame();
  }

  return { pass, results, failed, missingCoverage };
}

function v14RunSaveAudit({ saveResult = true } = {}) {
  const errors = [];
  const warnings = [];
  let raw = "";
  let parsed = null;

  try {
    saveGame();
    raw = localStorage.getItem(SAVE_KEY) || "";
    if (!raw) errors.push("セーブデータが空");
    parsed = raw ? JSON.parse(raw) : null;
  } catch (error) {
    errors.push("JSON読込失敗: " + (error?.message || String(error)));
  }

  if (parsed) {
    ["hunger", "energy", "mood", "clean", "birthTime", "metaProgress"].forEach(key => {
      if (!(key in parsed)) errors.push("必須キー不足: " + key);
    });

    try {
      const normalized = normalizeMetaProgress(parsed.metaProgress);
      if (normalized.v14?.saveSchema !== 14) errors.push("v14セーブスキーマ変換失敗");
      if (normalized.v13?.saveSchema !== 13) errors.push("v13互換データ変換失敗");
      const roundTrip = JSON.parse(JSON.stringify(parsed));
      if (!roundTrip || typeof roundTrip !== "object") errors.push("JSON往復変換失敗");
    } catch (error) {
      errors.push("正規化失敗: " + (error?.message || String(error)));
    }

    const validSlotIds = new Set(v12AssetSlots().map(slot => slot.id));
    Object.keys(parsed.metaProgress?.v12?.assetOverrides || {}).forEach(id => {
      if (!validSlotIds.has(id)) warnings.push("不明な画像枠ID: " + id);
    });
  }

  // 実際のlocalStorage書込→読込→削除を別キーで検査する。
  try {
    const tempKey = SAVE_KEY + "_v14WriteTest";
    localStorage.setItem(tempKey, raw || "{}");
    const readBack = localStorage.getItem(tempKey);
    localStorage.removeItem(tempKey);
    if (readBack !== (raw || "{}")) errors.push("localStorage書込・読込不一致");
  } catch (error) {
    errors.push("localStorage書込テスト失敗: " + (error?.message || String(error)));
  }

  const releaseBackup = localStorage.getItem(V14_RELEASE_BACKUP_KEY);
  if (releaseBackup) {
    try { JSON.parse(releaseBackup); }
    catch { warnings.push("リリース用バックアップが壊れている"); }
  }

  const pass = errors.length === 0;
  if (saveResult) {
    metaProgress.v14.lastSaveAuditAt = Date.now();
    metaProgress.v14.lastSaveAuditPassed = pass;
    if (pass) {
      const set = new Set(metaProgress.v13.completedFinalChecks || []);
      set.add("save");
      metaProgress.v13.completedFinalChecks = [...set];
    }
    saveGame();
  }
  return { pass, errors, warnings };
}

function v14MissingAssetsByCategory() {
  const groups = {};
  v12AssetSlots().forEach(slot => {
    if (!v12IsAssetApproved(slot)) {
      (groups[slot.category] ||= []).push(slot.label);
    }
  });
  return groups;
}

function v14RunReleaseAudit({ saveResult = true } = {}) {
  const integrity = v11RunIntegrityAudit({ saveResult: false });
  const route = v14RunRouteAudit({ saveResult: false });
  const save = v14RunSaveAudit({ saveResult: false });
  const assets = v12AssetProgress();
  const duplicates = v13ConfiguredDuplicates();
  const errorLogCount = (metaProgress.v11.errorLog || []).length;
  const blockers = [];
  const pending = [];

  if (integrity.errorCount) blockers.push("整合性エラー " + integrity.errorCount + "件");
  if (!route.pass) blockers.push("主要ルート診断失敗 " + route.failed.length + "件");
  if (!save.pass) blockers.push("セーブ復旧診断失敗 " + save.errors.length + "件");

  if (assets.approved < assets.total) pending.push("本番画像 " + assets.approved + "/" + assets.total + " 枠確定");
  if (duplicates.length) pending.push("画像URL重複 " + duplicates.length + "件");
  if (errorLogCount) pending.push("記録済みJavaScriptエラー " + errorLogCount + "件");
  if (!metaProgress.v13.lastFullRunAt) pending.push("高速通しテスト未記録");

  const status = blockers.length ? "BLOCK" : pending.length ? "PENDING" : "READY";
  if (saveResult) {
    metaProgress.v14.lastReleaseAuditAt = Date.now();
    metaProgress.v14.lastReleaseAuditStatus = status;
    if (route.pass) {
      metaProgress.v14.lastRouteAuditAt = Date.now();
      metaProgress.v14.lastRouteAuditPassed = true;
      metaProgress.v14.lastRouteAuditPassedCount = route.results.length;
      metaProgress.v14.lastRouteAuditTotalCount = route.results.length;
    }
    metaProgress.v14.lastSaveAuditAt = Date.now();
    metaProgress.v14.lastSaveAuditPassed = save.pass;
    saveGame();
  }

  return { status, blockers, pending, integrity, route, save, assets, duplicates, errorLogCount };
}

function v14CreateReleaseBackup() {
  saveGame();
  const raw = localStorage.getItem(SAVE_KEY);
  if (!raw) {
    showEventMessage("リリース用バックアップを作れなかった。セーブデータが空。" );
    return false;
  }
  try {
    JSON.parse(raw);
    localStorage.setItem(V14_RELEASE_BACKUP_KEY, raw);
    metaProgress.v14.lastReleaseBackupAt = Date.now();
    saveGame();
    showEventMessage("本番切替前の安全バックアップを保存した。" );
    refreshV14ReleasePanel();
    return true;
  } catch (error) {
    showEventMessage("バックアップ作成失敗：" + (error?.message || String(error)));
    return false;
  }
}

function v14RestoreReleaseBackup() {
  const raw = localStorage.getItem(V14_RELEASE_BACKUP_KEY);
  if (!raw) {
    showEventMessage("本番切替前バックアップはまだない。" );
    return;
  }
  try {
    JSON.parse(raw);
  } catch {
    showEventMessage("バックアップデータが壊れているため復元できない。" );
    return;
  }
  if (!confirm("本番切替前バックアップへ復元します。現在のセーブは上書きされます。よろしいですか？")) return;
  localStorage.setItem(SAVE_KEY, raw);
  location.reload();
}

function v14EnterProductionMode() {
  const audit = v14RunReleaseAudit({ saveResult: true });
  refreshV14ReleasePanel();
  if (audit.blockers.length) {
    showEventMessage("本番モード切替を停止：先にリリース診断のBLOCK項目を直して。" );
    return;
  }
  if (!v14CreateReleaseBackup()) return;
  v13SetProductionMode(true);
}

function v14ReleaseStatusLabel(status) {
  if (status === "READY") return "🟢 READY";
  if (status === "PENDING") return "🟡 仕上げ待ち";
  if (status === "BLOCK") return "🔴 要修正";
  return "⚪ 未診断";
}

function v14RouteReportText(audit) {
  return audit.results.map(item =>
    (item.pass ? "✅ " : "❌ ") + item.category + " / " + item.name +
    "　期待:" + item.expected + "　結果:" + item.actual
  ).join("\n") +
  (audit.missingCoverage.length ? "\n\n未到達ID：" + audit.missingCoverage.join(", ") : "");
}

function v14SaveReportText(audit) {
  const lines = [audit.pass ? "✅ セーブ診断 PASS" : "❌ セーブ診断 FAIL"];
  audit.errors.forEach(x => lines.push("ERROR: " + x));
  audit.warnings.forEach(x => lines.push("WARN: " + x));
  return lines.join("\n");
}

function v14ReleaseReportText(audit) {
  const missing = v14MissingAssetsByCategory();
  const lines = [
    GAME_TITLE + " v" + GAME_VERSION + " リリース診断",
    "診断日時：" + new Date().toLocaleString(),
    "判定：" + audit.status,
    "主要ルート：" + (audit.route.pass ? "PASS" : "FAIL"),
    "セーブ復旧：" + (audit.save.pass ? "PASS" : "FAIL"),
    "整合性エラー：" + audit.integrity.errorCount,
    "本番画像：" + audit.assets.approved + "/" + audit.assets.total,
    "画像URL重複：" + audit.duplicates.length,
    "記録済みJSエラー：" + audit.errorLogCount,
    "高速通しテスト：" + (metaProgress.v13.lastFullRunAt ? "済" : "未"),
    ""
  ];
  if (audit.blockers.length) {
    lines.push("【BLOCK】");
    audit.blockers.forEach(x => lines.push("・" + x));
    lines.push("");
  }
  if (audit.pending.length) {
    lines.push("【残作業】");
    audit.pending.forEach(x => lines.push("・" + x));
    lines.push("");
  }
  const cats = Object.entries(missing);
  if (cats.length) {
    lines.push("【未確定画像】");
    cats.forEach(([category, labels]) => lines.push("・" + category + "：" + labels.length + "枠 / " + labels.join("、")));
  }
  return lines.join("\n");
}

function v14InstallSecretDevUnlock() {
  if (!brandingEl || brandingEl.dataset.v14SecretUnlock === "1") return;
  brandingEl.dataset.v14SecretUnlock = "1";
  brandingEl.addEventListener("click", () => {
    if (!metaProgress.v13.productionMode) return;
    v14SecretTapCount += 1;
    clearTimeout(v14SecretTapTimer);
    v14SecretTapTimer = setTimeout(() => { v14SecretTapCount = 0; }, 3000);
    if (v14SecretTapCount >= 7) {
      v14SecretTapCount = 0;
      clearTimeout(v14SecretTapTimer);
      v13SetProductionMode(false);
      refreshV14ReleasePanel();
      showEventMessage("開発表示へ戻した。テストモードも再表示した。" );
    }
  });
}

