function gameLoop() {
  if (titleScreenOpen) return;

  if (zombieState.active) {
    applyZombieTimeDecay();
    checkZombiePhase();

    if (!isDead && zombieState.active) {
      checkRandomEvent();
    }
  } else if (!isDead) {
    applyTimeDecay();
    syncZeroTimer();
    checkGrowthTypes();
    resolveDeath();

    if (!isDead && !zombieState.active) {
      checkRandomEvent();
    }
  }

  checkProgressionRewards();
  updateStatus();
  updateView();
  refreshV10Dashboard();
  refreshV10ResultPanel();
  refreshDemonLaboEndFeedback();
  v11ApplyReleasePreview();
}

