/* =========================
   RC65 外部UI素材
   URL未設定時はDOMもCSSも追加しない。
========================= */
function createDemonLaboExternalUiAssetStyle() {
  const characterFrameUrl = demonLaboUiAssetUrl(DEMON_LABO_UI_ASSETS.characterFrame);
  const gameBackgroundUrl = demonLaboUiAssetUrl(DEMON_LABO_UI_ASSETS.gameBackground);

  if (!characterFrameUrl && !gameBackgroundUrl) return;
  if (document.getElementById("demonLaboExternalUiAssetStyle")) return;

  const style = document.createElement("style");
  style.id = "demonLaboExternalUiAssetStyle";

  const rules = [];

  if (gameBackgroundUrl) {
    rules.push(`
      body {
        background-image: url(${JSON.stringify(gameBackgroundUrl)}) !important;
        background-repeat: no-repeat !important;
        background-position: center top !important;
        background-size: cover !important;
        background-attachment: scroll !important;
      }
    `);
  }

  if (characterFrameUrl) {
    rules.push(`
      #demonLaboImageFrame {
        background-image: url(${JSON.stringify(characterFrameUrl)}) !important;
        background-repeat: no-repeat !important;
        background-position: center !important;
        background-size: 100% 100% !important;
      }
    `);
  }

  style.textContent = rules.join("\n");
  document.head.appendChild(style);
}


/* =========================
   RC67 スマホ実機判定レイアウト修正
   CodePenのPreviewではスマホでもCSSレイアウト幅が600pxを超える場合があり、
   max-widthメディアクエリだけではRC66が発火しない。
   実端末情報から「スマホ」を判定してクラスを付与し、
   そのクラスでHUDをキャラ画像の外へ確実に配置する。
========================= */
function applyDemonLaboPhoneDeviceClass() {
  const ua = String(navigator.userAgent || "");
  const uaPhone = /iPhone|iPod|Android.+Mobile|Windows Phone|IEMobile|Opera Mini|Mobile/i.test(ua);

  const screenW = Number(window.screen?.width || 9999);
  const screenH = Number(window.screen?.height || 9999);
  const shortScreenSide = Math.min(screenW, screenH);

  const visualW = Number(window.visualViewport?.width || window.innerWidth || 9999);

  // iPadは除外。スマホだけを対象にする。
  const looksLikeIPad = /iPad/i.test(ua) || (
    /Macintosh/i.test(ua) && Number(navigator.maxTouchPoints || 0) > 1 && shortScreenSide >= 700
  );

  const isPhone = !looksLikeIPad && (uaPhone || shortScreenSide <= 600 || visualW <= 600);
  const isIPad = looksLikeIPad;

  document.documentElement.classList.toggle("dl-phone-app-layout", isPhone);
  document.documentElement.classList.toggle("dl-ipad-app-layout", isIPad);
  if (document.body) {
    document.body.classList.toggle("dl-phone-app-layout", isPhone);
    document.body.classList.toggle("dl-ipad-app-layout", isIPad);
  }
  if (typeof refreshDemonLaboGrowthMeter === "function") refreshDemonLaboGrowthMeter();
  return isPhone;
}

