/* =========================
   RC81 外部レイアウト統合
   ・外部で作成した「名前 / 成長 / ステータス / キャラ / お世話」の構造を正解レイアウトとして採用
   ・ゲームロジック、セーブ、分岐、動画、アイテム等は既存のまま
   ・旧iPad補正を重ねず、実DOMを新しいステージへ移動してCSS競合を断つ
========================= */
function createDemonLaboExternalLayoutBridge() {
  if (document.getElementById("demonLaboExternalGame")) return;

  const shell = document.getElementById("demonLaboJellyShell");
  const heroCard = document.getElementById("demonLaboHeroCard");
  const heroMeta = document.getElementById("demonLaboHeroMeta");
  const growth = document.getElementById("demonLaboGrowthMeter");
  const status = document.getElementById("demonLaboTopStatus");
  const imageFrame = document.getElementById("demonLaboImageFrame");
  const careHint = document.getElementById("demonLaboCareHint");
  const feedback = document.getElementById("demonLaboActionFeedback");
  const actionGrid = document.getElementById("demonLaboActionGrid");

  if (!shell || !heroMeta || !growth || !status || !imageFrame || !careHint || !actionGrid) {
    return;
  }

  const game = document.createElement("main");
  game.id = "demonLaboExternalGame";
  game.className = "game dl-external-game";

  const top = document.createElement("div");
  top.className = "dl-external-top";

  const playfield = document.createElement("section");
  playfield.className = "dl-external-playfield";

  const bottom = document.createElement("div");
  bottom.className = "dl-external-bottom";

  top.appendChild(heroMeta);
  top.appendChild(growth);

  /*
    #demonLaboTopStatus 自体をプレイフィールドにする。
    4枚のステータスカードは直下のままなので、
    既存の数値更新処理とスキンを壊さない。
  */
  status.classList.add("dl-external-status-field");
  status.appendChild(imageFrame);
  playfield.appendChild(status);

  bottom.appendChild(careHint);
  if (feedback) bottom.appendChild(feedback);
  bottom.appendChild(actionGrid);

  game.appendChild(top);
  game.appendChild(playfield);
  game.appendChild(bottom);

  const lowerStack = document.getElementById("demonLaboLowerStack");
  if (lowerStack && lowerStack.parentNode === shell) {
    shell.insertBefore(game, lowerStack);
  } else if (heroCard && heroCard.parentNode === shell) {
    shell.insertBefore(game, heroCard);
  } else {
    shell.prepend(game);
  }

  if (heroCard) {
    heroCard.style.setProperty("display", "none", "important");
  }

  document.documentElement.classList.add("dl-external-layout-active");
  document.body.classList.add("dl-external-layout-active");

  /*
    旧レイアウトがDOMへ残したインライン位置指定だけ解除。
    見た目やゲーム状態は触らない。
  */
  const resetInlineLayout = el => {
    if (!el) return;
    [
      "position", "inset", "top", "right", "bottom", "left",
      "width", "height", "max-width", "max-height", "min-width", "min-height",
      "margin", "padding", "transform", "display", "grid-column", "grid-row"
    ].forEach(prop => el.style.removeProperty(prop));
  };

  [
    heroMeta, growth, status, imageFrame,
    document.getElementById("demonLaboCharacterMedia"),
    document.getElementById("characterImage"),
    document.getElementById("characterVideo"),
    careHint, feedback, actionGrid
  ].forEach(resetInlineLayout);

  updateStatus();
  updateView();
  syncDemonLaboCuteParameterUI();
  refreshDemonLaboGrowthMeter();
}


