/* =========================
   RC88 スマホ4ステータス強制配置
   CSSの後勝ち競合ではなく、スマホ時だけDOMへ直接配置を指定する。
   体力・清潔度が右側画面外へ飛ぶ問題を根本修正。
========================= */
function enforceDemonLaboSmartphoneFourStats() {
  const status = document.getElementById("demonLaboTopStatus");
  const imageFrame = document.getElementById("demonLaboImageFrame");

  const cards = [
    { id: "dlParamHunger", column: "1", row: "1" },
    { id: "dlParamEnergy", column: "2", row: "1" },
    { id: "dlParamMood", column: "1", row: "2" },
    { id: "dlParamClean", column: "2", row: "2" }
  ];

  if (!status) return;

  // CodePen Preview はスマホ実機でも window.innerWidth が 700px 超になることがある。
  // 既存の実機判定クラスを最優先し、幅判定だけに依存しない。
  const isPhone =
    document.documentElement.classList.contains("dl-phone-app-layout") ||
    document.body?.classList.contains("dl-phone-app-layout") ||
    /iPhone|iPod|Android.+Mobile|Windows Phone|IEMobile|Opera Mini|Mobile/i.test(
      String(navigator.userAgent || "")
    ) ||
    Math.min(
      Number(window.screen?.width || 9999),
      Number(window.screen?.height || 9999)
    ) <= 600 ||
    Number(window.visualViewport?.width || 9999) <= 600 ||
    window.innerWidth <= 699;

  const setImportant = (el, prop, value) => {
    if (!el) return;
    el.style.setProperty(prop, value, "important");
  };

  const clear = (el, props) => {
    if (!el) return;
    props.forEach(prop => el.style.removeProperty(prop));
  };

  if (!isPhone) {
    clear(status, [
      "display",
      "grid-template-columns",
      "grid-template-rows",
      "gap",
      "height",
      "min-height",
      "padding"
    ]);

    cards.forEach(({ id }) => {
      const card = document.getElementById(id);
      clear(card, [
        "display",
        "visibility",
        "opacity",
        "position",
        "inset",
        "top",
        "right",
        "bottom",
        "left",
        "grid-column",
        "grid-row",
        "width",
        "height",
        "min-height",
        "margin",
        "transform",
        "z-index"
      ]);
    });

    clear(imageFrame, ["grid-column", "grid-row"]);
    return;
  }

  setImportant(status, "display", "grid");
  setImportant(status, "grid-template-columns", "repeat(2, minmax(0, 1fr))");
  setImportant(status, "grid-template-rows", "auto auto minmax(430px, 1fr)");
  setImportant(status, "gap", "5px");
  setImportant(status, "height", "auto");
  setImportant(status, "min-height", "0");
  setImportant(status, "padding", "0");

  cards.forEach(({ id, column, row }) => {
    const card = document.getElementById(id);
    if (!card) return;

    setImportant(card, "display", "block");
    setImportant(card, "visibility", "visible");
    setImportant(card, "opacity", "1");
    setImportant(card, "position", "relative");
    setImportant(card, "inset", "auto");
    setImportant(card, "top", "auto");
    setImportant(card, "right", "auto");
    setImportant(card, "bottom", "auto");
    setImportant(card, "left", "auto");
    setImportant(card, "grid-column", column);
    setImportant(card, "grid-row", row);
    setImportant(card, "width", "100%");
    setImportant(card, "height", "42px");
    setImportant(card, "min-height", "42px");
    setImportant(card, "margin", "0");
    setImportant(card, "transform", "none");
    setImportant(card, "z-index", "7");
  });

  if (imageFrame) {
    setImportant(imageFrame, "grid-column", "1 / -1");
    setImportant(imageFrame, "grid-row", "3");
  }
}

